# -*- coding: utf-8 -*-
"""program_compiler.py - v2.3 Program Compiler (deterministic rendering).

Power boundary (frozen v2.3 contract):
  Analysis/HERA choose the method + parameters (MethodInvocationV1). The
  compiler ONLY validates the invocation against the Capability Registry
  and the dataset contract, then deterministically renders a runnable
  script from a frozen template. It never invents methods and never
  modifies research choices. Repair-time parameter patches are strictly
  crash-driven micro-adjustments (halve a budget/convergence knob), never
  research decisions.

Phase C (capability synthesis): the LLM writes ONE adapter template once
(an sklearn-compatible estimator builder). The compiler wraps it in the
same deterministic harness, so later children only change parameters.
A synthesized capability is validated by trial; failures mark it broken.
"""
import hashlib
import json
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Tuple

from capability_registry import CapabilityRegistry, MethodSpec
from v2_contracts import MethodInvocationV1

TEMPLATE_SCHEMA = "v250_template_v1"

# v2.5.0 declarative modality vocabulary (data, not branching).
_KNOWN_MODALITIES = ("image", "image_pixel", "image_mask",
                    "image_detection", "audio", "tabular",
                    "text", "mixed", "unknown", "")

_TABULAR_HARNESS = '# -*- coding: utf-8 -*-\n# v2.3.4 ProgramCompiler deterministic render (multi-output regression + sample-driven targets). Template hash is frozen at\n# seal time; every child with the same invocation renders bit-identical code.\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\n\ndef log(msg):\n    print(\"[compiled] %s\" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get(\"TRAIN_CSV\") or \"train.csv\"\nTEST_CSV = os.environ.get(\"TEST_CSV\") or \"test.csv\"\nSAMPLE_SUB = os.environ.get(\"SAMPLE_SUBMISSION\") or \"\"\nTARGET_COL = (os.environ.get(\"TARGET_COLUMN\") or \"\").strip()\nTASK_TYPE = (os.environ.get(\"TASK_TYPE\") or \"classification\").lower()\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nPREPROC = json.loads(\'@@PREPROCESSING_JSON@@\')\nTEXT_COLUMNS = json.loads(\'@@TEXT_COLUMNS_JSON@@\') or []\nLAG_COLUMN = \'@@LAG_COLUMN@@\'\nDATETIME_COLUMNS = json.loads(\'@@DATETIME_COLUMNS_JSON@@\') or []\nMODALITY = \'@@MODALITY@@\'\nif not MODALITY and TEXT_COLUMNS:\n    # legacy manifests (pre-v2.3.3 resume) have no modality field:\n    # baked text columns mean the text branch was intended.\n    MODALITY = \"text\"\nVALIDATION = \'@@VALIDATION@@\'\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nMETRIC_KIND = \'@@METRIC_KIND@@\'\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get(\"val_seed\", 42))\nrandom.seed(SEED)\nnp.random.seed(SEED)\n\ndf_train = pd.read_csv(TRAIN_CSV)\ndf_test = pd.read_csv(TEST_CSV)\n\n# ------------------------------------------------------------------ id column\nsample_header = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    try:\n        sample_header = [str(c) for c in pd.read_csv(SAMPLE_SUB, nrows=0).columns]\n    except Exception:\n        sample_header = []\n# v2.5.5: sample passthrough = sample-submission columns that exist in\n# test.csv (in sample order); the FIRST passthrough column is the join id.\n# Handles no-id sample headers (target first, e.g. Insult,Date,Comment) -\n# sample column 0 is never assumed to be the id.\nSAMPLE_PASSTHROUGH = [str(c) for c in sample_header if str(c) in df_test.columns]\nSAMPLE_OUTPUT = [str(c) for c in sample_header if str(c) not in df_test.columns]\nid_col = SAMPLE_PASSTHROUGH[0] if SAMPLE_PASSTHROUGH else None\nif id_col is None or id_col not in df_test.columns:\n    id_col = next((c for c in (\"id\", \"Id\", \"ID\", \"index\") if c in df_test.columns), None)\nif id_col is None or id_col not in df_test.columns:\n    id_col = str(df_test.columns[0])\n# v2.5.6 compound-id synthesis: when the sample id column is absent from\n# test.csv but equals a \"_\"-join of test columns (e.g. \"sentence_id\" +\n# \"token_id\" -> \"0_0\"), synthesize the join key so every sample row maps\n# to exactly one test row.\nSYN_COLS = []\n_SYN_ID_COL = \"\"\nif not SAMPLE_PASSTHROUGH and sample_header:\n    _sid = str(sample_header[0])\n    _test_cols = [str(c) for c in df_test.columns]\n    _sample_ids = None\n    try:\n        _sdf = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        if _sid in _sdf.columns:\n            _sample_ids = [str(v).strip() for v in _sdf[_sid].values]\n    except Exception:\n        _sample_ids = None\n    if _sample_ids and _test_cols:\n        _check_n = min(200, len(_sample_ids))\n\n        def _matches(cols):\n            if not cols:\n                return False\n            for k in range(_check_n):\n                parts = [str(df_test[c].astype(str).iloc[k]).strip()\n                         for c in cols]\n                if \"_\".join(parts) != _sample_ids[k]:\n                    return False\n            return True\n\n        _found = []\n        for c in _test_cols:\n            if _matches([c]):\n                _found = [c]\n                break\n        if not _found and len(_test_cols) <= 12:\n            for i in range(len(_test_cols)):\n                for j in range(i + 1, len(_test_cols)):\n                    if _matches([_test_cols[i], _test_cols[j]]):\n                        _found = [_test_cols[i], _test_cols[j]]\n                        break\n                if _found:\n                    break\n        if _found:\n            SYN_COLS = _found\n            _SYN_ID_COL = _sid\n            SAMPLE_PASSTHROUGH = list(_found)\n            id_col = _found[0]\n            log(\"compound id: %s = %s\" % (_sid, \"+\".join(_found)))\n            SAMPLE_OUTPUT = [str(c) for c in SAMPLE_OUTPUT\n                            if str(c) != _SYN_ID_COL]\n\n\n\nif not TARGET_COL or TARGET_COL not in df_train.columns:\n    cands = [str(c) for c in df_train.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df_train.columns[-1])\n\n# v2.5.5: sample-submission-driven targets. Ground-truth prediction\n# columns are exactly the sample-submission columns that are NOT in\n# test.csv (the rest are id/passthrough columns). This fixes label\n# detection for tasks whose labels table ends with a non-target column,\n# enables multi-output regression, and handles no-id sample headers\n# where the FIRST sample column is the target (Insult,Date,Comment).\n# Generic - never competition-specific.\nis_classification = TASK_TYPE == \"classification\"\nSAMPLE_TARGETS = [str(c) for c in sample_header\n                  if str(c) not in df_test.columns\n                  and str(c) in df_train.columns and str(c) != id_col]\nif len(SAMPLE_TARGETS) > 1 and not is_classification:\n    TARGET_COLS = SAMPLE_TARGETS\nelif len(SAMPLE_TARGETS) == 1:\n    TARGET_COLS = SAMPLE_TARGETS\nelse:\n    TARGET_COLS = [TARGET_COL]\nif TARGET_COL not in TARGET_COLS:\n    TARGET_COL = TARGET_COLS[0]\nMULTI_TARGET = len(TARGET_COLS) > 1\n\nfeature_cols = [str(c) for c in df_train.columns\n                if str(c) not in (id_col,) and str(c) not in TARGET_COLS]\ny_all = df_train[TARGET_COL].astype(str).values\nif MULTI_TARGET:\n    y_fit = df_train[TARGET_COLS].astype(\"float64\").values\nelse:\n    y_fit = y_all\ntest_ids = df_test[id_col].astype(str).values\nn = len(df_train)\nclasses_ = sorted(set(y_all)) if is_classification else []\nn_classes = len(classes_)\n\n# ------------------------------------------------------- feature engineering\ndef _encode_feature(tr, te):\n    if pd.api.types.is_numeric_dtype(tr) and not pd.api.types.is_bool_dtype(tr):\n        out_tr = tr.astype(\"float64\").values\n        out_te = (te.astype(\"float64\").values if te is not None else None)\n        return out_tr, out_te\n    if \"frequency_encoding\" in PREPROC:\n        cnt = tr.value_counts()\n        m = cnt / max(1, len(tr))\n        out_tr = tr.map(m).astype(\"float64\").values\n        out_te = (te.map(m).fillna(0.0).astype(\"float64\").values\n                  if te is not None else None)\n        return out_tr, out_te\n    cats = sorted(set(tr.dropna().unique()), key=lambda v: str(v))\n    mapping = {v: i for i, v in enumerate(cats)}\n    out_tr = tr.map(mapping).fillna(-1.0).astype(\"float64\").values\n    out_te = (te.map(mapping).fillna(-1.0).astype(\"float64\").values\n              if te is not None else None)\n    return out_tr, out_te\n\n_LAG_MODE = bool(LAG_COLUMN) and LAG_COLUMN in df_train.columns\n\nif _LAG_MODE:\n    # ---- timeseries (v2.3.2): time-ordered lag / rolling features ----\n    _dt_tr = pd.to_datetime(df_train[LAG_COLUMN], errors=\"coerce\")\n    if LAG_COLUMN in df_test.columns:\n        _dt_te = pd.to_datetime(df_test[LAG_COLUMN], errors=\"coerce\")\n    else:\n        _dt_te = pd.Series([pd.NaT] * len(df_test))\n    _ord_tr = _dt_tr.astype(\"int64\").values / 1e9\n    _ord_te = _dt_te.astype(\"int64\").values / 1e9\n    _order = np.argsort(_ord_tr, kind=\"mergesort\")\n    df_train = df_train.iloc[_order].reset_index(drop=True)\n    y_all = df_train[TARGET_COL].astype(str).values\n    _ord_tr = _ord_tr[_order]\n    n = len(df_train)\n    _max_lag = max(1, int(PARAMS.get(\"max_lag\", 7) or 7))\n    _roll = max(0, int(PARAMS.get(\"rolling_window\", 7) or 7))\n    _lag_parts = []\n    for c in df_train.columns:\n        if c in (TARGET_COL, id_col, LAG_COLUMN) or c in TEXT_COLUMNS:\n            continue\n        _s_tr = pd.to_numeric(df_train[c], errors=\"coerce\").astype(\"float64\")\n        if c in df_test.columns:\n            _s_te = pd.to_numeric(df_test[c], errors=\"coerce\").astype(\"float64\")\n        else:\n            _s_te = pd.Series([np.nan] * len(df_test))\n        for _L in sorted({1, 2, 3, _max_lag}):\n            _lag_parts.append((\"lag%d_%s\" % (_L, c),\n                               _s_tr.shift(_L), _s_te.shift(_L)))\n        if _roll > 0:\n            _lag_parts.append((\"rmean%d_%s\" % (_roll, c),\n                               _s_tr.rolling(_roll, min_periods=2).mean(),\n                               _s_te.rolling(_roll, min_periods=2).mean()))\n            _lag_parts.append((\"rstd%d_%s\" % (_roll, c),\n                               _s_tr.rolling(_roll, min_periods=2).std(),\n                               _s_te.rolling(_roll, min_periods=2).std()))\n    if _lag_parts:\n        _L_tr = pd.DataFrame({k: v for k, v, _ in _lag_parts})\n        _L_te = pd.DataFrame({k: v for _, _, v in _lag_parts})\n        _keep = _L_tr.notna().all(axis=1).values\n        _lag_tr = _L_tr[_keep].fillna(0.0).values.astype(\"float64\")\n        _lag_te = _L_te.fillna(0.0).values.astype(\"float64\")\n    else:\n        # every feature column is id/target/date: keep rows, ordinal only\n        _keep = np.ones(n, dtype=bool)\n        _lag_tr = np.zeros((n, 0))\n        _lag_te = np.zeros((len(df_test), 0))\n    df_train = df_train[_keep].reset_index(drop=True)\n    y_all = y_all[_keep]\n    if MULTI_TARGET:\n        y_fit = y_fit[_keep]\n    _ord_tr = _ord_tr[_keep]\n    n = len(df_train)\n    X_all = np.column_stack([_ord_tr.reshape(-1, 1), _lag_tr])\n    X_test = np.column_stack([_ord_te.reshape(-1, 1), _lag_te])\n    VALIDATION = \"time_holdout\"\n    log(\"lag features: %d cols train_rows=%d\" % (X_all.shape[1], n))\n\nif not _LAG_MODE:\n    # ---- v2.5.1: datetime feature derivation (declarative prior) ----\n    # A content-verified date/time column must NEVER be ordinal-encoded:\n    # trees split on the 0..N ordinal axis and extrapolate to physically\n    # impossible leaf values (real taxi runs produced -30..+1242 fares).\n    # Calendar + elapsed features are the generic registry prior; the\n    # planner may override through preprocessing options\n    # (\"datetime_ordinal\" / \"datetime_drop\").\n    _datetime_mode = \"derive\" if DATETIME_COLUMNS else \"none\"\n    if \"datetime_ordinal\" in PREPROC:\n        _datetime_mode = \"ordinal\"\n    elif \"datetime_drop\" in PREPROC:\n        _datetime_mode = \"drop\"\n    if _datetime_mode == \"drop\":\n        _drop_dt = [c for c in feature_cols if c in DATETIME_COLUMNS]\n        feature_cols = [c for c in feature_cols if c not in DATETIME_COLUMNS]\n        if _drop_dt:\n            log(\"datetime drop: %s\" % \",\".join(_drop_dt))\n    elif _datetime_mode == \"derive\":\n        _dt_new = []\n        for _dc in DATETIME_COLUMNS:\n            if _dc not in feature_cols:\n                continue\n            _ts_tr = pd.to_datetime(df_train[_dc], errors=\"coerce\")\n            if _dc in df_test.columns:\n                _ts_te = pd.to_datetime(df_test[_dc], errors=\"coerce\")\n            else:\n                _ts_te = pd.Series([pd.NaT] * len(df_test))\n            _valid = _ts_tr.dropna()\n            if _valid.empty:\n                continue\n            _ref = _valid.median()\n            for _sfx, _fn in ((\"year\", lambda d: d.dt.year),\n                              (\"month\", lambda d: d.dt.month),\n                              (\"day\", lambda d: d.dt.day),\n                              (\"dow\", lambda d: d.dt.dayofweek),\n                              (\"hour\", lambda d: d.dt.hour),\n                              (\"elapsed\", lambda d: (d - _ref).dt.total_seconds())):\n                _cn = \"__dt_%s_%s\" % (_sfx, _dc)\n                df_train[_cn] = _fn(_ts_tr).astype(\"float64\").fillna(-1.0)\n                df_test[_cn] = _fn(_ts_te).astype(\"float64\").fillna(-1.0)\n                _dt_new.append(_cn)\n            log(\"datetime derive %s -> 6 features\" % _dc)\n        feature_cols = ([c for c in feature_cols if c not in DATETIME_COLUMNS]\n                        + _dt_new)\n        if _dt_new:\n            log(\"datetime feature cols: %d\" % len(_dt_new))\n    # ---- text vs plain feature split (content-verified text columns) ----\n    # v2.3.3: free-text features only for text modality. A stray text\n    # column (e.g. passenger Name) in a tabular task is dropped so dense\n    # tabular models (HistGB/MLP) never receive sparse input.\n    _text_cols = [c for c in feature_cols\n                  if c in TEXT_COLUMNS and MODALITY == \"text\"]\n    _plain_cols = [c for c in feature_cols if c not in _text_cols]\n    _stray_text = [c for c in feature_cols\n                   if c in TEXT_COLUMNS and c not in _text_cols]\n    if _stray_text:\n        log(\"tabular mode: dropping %d text column(s): %s\"\n            % (len(_stray_text), \",\".join(_stray_text)))\n    _text_tr, _text_te = [], []\n    if _text_cols:\n        from scipy.sparse import csr_matrix as _csr, hstack as _sph\n        from sklearn.feature_extraction.text import TfidfVectorizer\n        _mfe = max(2000, int(PARAMS.get(\"max_features\", 20000) or 20000)\n                   // max(1, len(_text_cols)))\n        _ng = max(1, min(3, int(PARAMS.get(\"ngram_max\", 2) or 2)))\n        _md = max(1, int(PARAMS.get(\"min_df\", 2) or 2))\n        for _c in _text_cols:\n            _tr_s = df_train[_c].fillna(\"\").astype(str)\n            if _c in df_test.columns:\n                _te_s = df_test[_c].fillna(\"\").astype(str)\n            else:\n                _te_s = pd.Series([\"\"] * len(df_test))\n            _v = TfidfVectorizer(max_features=_mfe, ngram_range=(1, _ng),\n                                 min_df=_md, sublinear_tf=True,\n                                 dtype=np.float32)\n            _text_tr.append(_v.fit_transform(_tr_s.values))\n            _text_te.append(_v.transform(_te_s.values))\n        _S_tr = _text_tr[0] if len(_text_tr) == 1 else _sph(_text_tr).tocsr()\n        _S_te = _text_te[0] if len(_text_te) == 1 else _sph(_text_te).tocsr()\n    if _plain_cols:\n        _parts_tr, _parts_te = [], []\n        for c in _plain_cols:\n            a, b = _encode_feature(df_train[c],\n                                   df_test[c] if c in df_test.columns else None)\n            _parts_tr.append(a)\n            _parts_te.append(b if b is not None else np.zeros((len(df_test),)))\n        D_tr = np.column_stack(_parts_tr)\n        D_te = np.column_stack(_parts_te)\n    else:\n        D_tr = np.zeros((n, 1))\n        D_te = np.zeros((len(df_test), 1))\n\n    _impute = \"none\"\n    if \"missing_value_impute\" in PREPROC:\n        _impute = str(PARAMS.get(\"missing\", \"mean\"))\n    elif str(PARAMS.get(\"missing\", \"none\")) in (\"mean\", \"median\"):\n        _impute = str(PARAMS.get(\"missing\"))\n    if _impute != \"none\":\n        for j in range(D_tr.shape[1]):\n            col = D_tr[:, j]\n            finite = col[np.isfinite(col)]\n            if len(finite) == 0:\n                fill = 0.0\n            elif _impute == \"median\":\n                fill = float(np.median(finite))\n            else:\n                fill = float(np.mean(finite))\n            D_tr[np.isnan(D_tr[:, j]), j] = fill\n            D_te[np.isnan(D_te[:, j]), j] = fill\n\n    if \"standard_scaling\" in PREPROC or str(PARAMS.get(\"scaling\", \"none\")) == \"standard\":\n        from sklearn.preprocessing import StandardScaler\n        _sc = StandardScaler()\n        D_tr = _sc.fit_transform(D_tr)\n        D_te = _sc.transform(D_te)\n\n    if _text_cols:\n        X_all = _sph([_S_tr, _csr(D_tr)]).tocsr()\n        X_test = _sph([_S_te, _csr(D_te)]).tocsr()\n        log(\"text features: %d text cols, %d plain cols, X=%s\"\n            % (len(_text_cols), len(_plain_cols), X_all.shape))\n    else:\n        X_all = D_tr\n        X_test = D_te\n\n\ndef _strat_ok(y):\n    \"\"\"Stratification is only safe when every class has >= 2 members.\"\"\"\n    if len(y) < 2:\n        return False\n    from collections import Counter\n    counts = Counter(str(v) for v in y)\n    return len(counts) >= 2 and min(counts.values()) >= 2\n\n\ndef _holdout_split(test_size, seed, stratify_y=None):\n    from sklearn.model_selection import train_test_split\n    args = dict(test_size=test_size, random_state=seed)\n    if stratify_y is not None and _strat_ok(stratify_y):\n        args[\"stratify\"] = stratify_y\n    return train_test_split(np.arange(n), **args)\n\n\n# ----------------------------------------------------------- row cap (hint)\nsel_idx = np.arange(n)\nif MAX_TRAIN_ROWS > 0 and n > MAX_TRAIN_ROWS:\n    if is_classification and n_classes > 1 and _strat_ok(y_all):\n        from sklearn.model_selection import train_test_split\n        _sel, _ = train_test_split(np.arange(n), train_size=int(MAX_TRAIN_ROWS),\n                                   random_state=SEED, stratify=y_all)\n        sel_idx = np.sort(_sel)\n    else:\n        _rng = np.random.RandomState(SEED)\n        sel_idx = np.sort(_rng.choice(n, size=int(MAX_TRAIN_ROWS), replace=False))\n    X_all = X_all[sel_idx]\n    y_all = y_all[sel_idx]\n    y_fit = y_fit[sel_idx]\n    n = len(y_all)\n\n# ------------------------------------------------------------ model builders\ndef _BUILD_SINGLE(mid, seed):\n    if mid == \"tabular.linear.logistic.v1\":\n        _C = float(PARAMS.get(\"C\", 1.0))\n        _mi = int(PARAMS.get(\"max_iter\", 1000))\n        if is_classification:\n            from sklearn.linear_model import LogisticRegression\n            return LogisticRegression(C=_C, max_iter=_mi, solver=\"lbfgs\",\n                                      n_jobs=1, random_state=seed)\n        from sklearn.linear_model import Ridge\n        return Ridge(alpha=max(1e-6, 1.0 / _C), random_state=seed)\n    if mid == \"tabular.gbdt.histgb.v1\":\n        _lr = float(PARAMS.get(\"learning_rate\", 0.05))\n        _mln = int(PARAMS.get(\"max_leaf_nodes\", 64))\n        _mi = int(PARAMS.get(\"max_iter\", 300))\n        _l2 = float(PARAMS.get(\"l2_regularization\", 1.0))\n        _es = bool(PARAMS.get(\"early_stopping\", True)) and n >= 2000\n        if is_classification:\n            from sklearn.ensemble import HistGradientBoostingClassifier\n            return HistGradientBoostingClassifier(\n                learning_rate=_lr, max_leaf_nodes=_mln, max_iter=_mi,\n                l2_regularization=_l2, early_stopping=_es, random_state=seed)\n        from sklearn.ensemble import HistGradientBoostingRegressor\n        return HistGradientBoostingRegressor(\n            learning_rate=_lr, max_leaf_nodes=_mln, max_iter=_mi,\n            l2_regularization=_l2, early_stopping=_es, random_state=seed)\n    if mid == \"tabular.neural.mlp.v1\":\n        _hl = int(PARAMS.get(\"hidden_layers\", 2))\n        _hu = int(PARAMS.get(\"hidden_units\", 128))\n        _alpha = float(PARAMS.get(\"alpha\", 1e-3))\n        _lri = float(PARAMS.get(\"learning_rate_init\", 1e-3))\n        _mi = int(PARAMS.get(\"max_iter\", 500))\n        _es = bool(PARAMS.get(\"early_stopping\", True))\n        _hsz = tuple([_hu] * _hl)\n        _bs = min(256, max(32, n // 4))\n        if is_classification:\n            from sklearn.neural_network import MLPClassifier\n            return MLPClassifier(hidden_layer_sizes=_hsz, alpha=_alpha,\n                                 learning_rate_init=_lri, max_iter=_mi,\n                                 early_stopping=_es, batch_size=_bs,\n                                 random_state=seed)\n        from sklearn.neural_network import MLPRegressor\n        return MLPRegressor(hidden_layer_sizes=_hsz, alpha=_alpha,\n                            learning_rate_init=_lri, max_iter=_mi,\n                            early_stopping=_es, batch_size=_bs,\n                            random_state=seed)\n    if mid == \"text.embedding.tfidf.v1\":\n        _C = float(PARAMS.get(\"C\", 1.0))\n        _mi = int(PARAMS.get(\"max_iter\", 1000))\n        if is_classification:\n            from sklearn.linear_model import LogisticRegression\n            return LogisticRegression(C=_C, max_iter=_mi, solver=\"lbfgs\",\n                                      n_jobs=1, random_state=seed)\n        from sklearn.linear_model import Ridge\n        return Ridge(alpha=max(1e-6, 1.0 / _C), random_state=seed)\n    if mid == \"text.neural.mlp.v1\":\n        _hu = int(PARAMS.get(\"hidden_units\", 128))\n        _alpha = float(PARAMS.get(\"alpha\", 1e-3))\n        _mi = int(PARAMS.get(\"max_iter\", 500))\n        _bs = min(256, max(32, n // 4))\n        if is_classification:\n            from sklearn.neural_network import MLPClassifier\n            return MLPClassifier(hidden_layer_sizes=(_hu, _hu), alpha=_alpha,\n                                 max_iter=_mi, early_stopping=True,\n                                 batch_size=_bs, random_state=seed)\n        from sklearn.neural_network import MLPRegressor\n        return MLPRegressor(hidden_layer_sizes=(_hu, _hu), alpha=_alpha,\n                            max_iter=_mi, early_stopping=True,\n                            batch_size=_bs, random_state=seed)\n    if mid == \"timeseries.lag_histgb.v1\":\n        _lr = float(PARAMS.get(\"learning_rate\", 0.05))\n        _mln = int(PARAMS.get(\"max_leaf_nodes\", 64))\n        _mi = int(PARAMS.get(\"max_iter\", 300))\n        _l2 = float(PARAMS.get(\"l2_regularization\", 1.0))\n        _es = bool(PARAMS.get(\"early_stopping\", True)) and n >= 2000\n        if is_classification:\n            from sklearn.ensemble import HistGradientBoostingClassifier\n            return HistGradientBoostingClassifier(\n                learning_rate=_lr, max_leaf_nodes=_mln, max_iter=_mi,\n                l2_regularization=_l2, early_stopping=_es, random_state=seed)\n        from sklearn.ensemble import HistGradientBoostingRegressor\n        return HistGradientBoostingRegressor(\n            learning_rate=_lr, max_leaf_nodes=_mln, max_iter=_mi,\n            l2_regularization=_l2, early_stopping=_es, random_state=seed)\n    raise RuntimeError(\"compiled: unknown tabular method \" + str(mid))\n\n@@FRAGMENT@@\n\n# --------------------------------------------------------------- prediction\n_BINARY_PROBA = is_classification and n_classes == 2 and \\\n    METRIC_NAME in (\"auc\", \"binary_logloss\")\n_MULTI_PROBA = METRIC_KIND == \"proba\" and is_classification and not _BINARY_PROBA\n\ndef predict(est, X):\n    if _MULTI_PROBA:\n        P = est.predict_proba(X)\n        if P.shape[1] != len(classes_) or list(est.classes_) != classes_:\n            P2 = np.zeros((P.shape[0], len(classes_)))\n            cls = [str(c) for c in est.classes_]\n            for i, c in enumerate(cls):\n                if c in classes_:\n                    P2[:, classes_.index(c)] = P[:, i]\n            return P2\n        return P\n    if _BINARY_PROBA:\n        P = est.predict_proba(X)\n        return P[:, 1] if P.shape[1] == 2 else P[:, 0]\n    return est.predict(X)\n\n# ------------------------------------------------------------------ CV + OOF\noof_order = []\noof_true_by_idx = {}\noof_vec_by_idx = {}\noof_mat = None\nif _MULTI_PROBA:\n    oof_mat = np.full((n, n_classes), np.nan)\n\ndef _record(j, true_v, pred_v):\n    oof_order.append(int(j))\n    oof_true_by_idx[int(j)] = str(true_v)\n    if oof_mat is not None:\n        oof_mat[int(j)] = np.asarray(pred_v, dtype=\"float64\")\n    else:\n        if MULTI_TARGET:\n            pv = np.asarray(pred_v, dtype=\"float64\")\n            pred_v = pv[0] if pv.ndim > 0 else pv\n        oof_vec_by_idx[int(j)] = pred_v\n\nclass _ConstantPredictor:\n    \"\"\"Degenerate-fold fallback: majority class / mean value, no fit.\"\"\"\n    def __init__(self, is_class, classes_global):\n        self.is_class = bool(is_class)\n        self.value = \"0\"\n        self.multi_k = 1\n        self.classes_ = classes_global or []\n\n    def fit(self, X, y):\n        if self.is_class:\n            vals = [str(v) for v in y]\n        else:\n            y = np.asarray(y, dtype=\"float64\")\n            if y.ndim > 1:\n                self.multi_k = y.shape[1]\n                y = y[:, 0]\n            vals = [str(v) for v in y]\n        if vals:\n            from collections import Counter\n            self.value = Counter(vals).most_common(1)[0][0]\n        if self.is_class and not self.classes_:\n            self.classes_ = sorted(set(vals))\n        return self\n\n    def predict(self, X):\n        if self.is_class:\n            return np.array([self.value] * len(X))\n        try:\n            v = float(self.value)\n        except (TypeError, ValueError):\n            return np.zeros(len(X))\n        if self.multi_k > 1:\n            return np.full((len(X), self.multi_k), v)\n        return np.full(len(X), v)\n\n    def predict_proba(self, X):\n        n = len(X)\n        cols = [str(c) for c in (self.classes_ or [])]\n        if not cols:\n            return np.ones((n, 1))\n        out = np.zeros((n, len(cols)))\n        if self.value in cols:\n            out[:, cols.index(self.value)] = 1.0\n        else:\n            out[:, 0] = 1.0\n        return out\n\n\ndef _wrap_multi(est):\n    \"\"\"Multi-output regression (e.g. nomad2018: formation_energy_ev_natom\n    + bandgap_energy_ev) wraps every estimator in MultiOutputRegressor so\n    any sklearn version can fit 2-D y; single-target tasks stay untouched.\"\"\"\n    if MULTI_TARGET and not is_classification:\n        from sklearn.multioutput import MultiOutputRegressor\n        return MultiOutputRegressor(est, n_jobs=1)\n    return est\n\n\ndef _safe_fit(est, X, y):\n    \"\"\"Fit est unless the fold is degenerate (too few rows or, for\n    classification, fewer than 2 classes). Degenerate folds use a constant\n    majority predictor so OOF/submission stay valid. Generic MLE-bench\n    robustness: some competitions are tiny or extremely skewed.\"\"\"\n    n_fit = len(y)\n    if n_fit < 2:\n        return _ConstantPredictor(is_classification, classes_)\n    if is_classification and len({str(v) for v in y}) < 2:\n        return _ConstantPredictor(is_classification, classes_)\n    est.fit(X, y)\n    return est\n\n\ndef _run_cv():\n    from sklearn.model_selection import train_test_split\n    if VALIDATION == \"time_holdout\":\n        # strict time-ordered split: last 25% of rows (sorted by the\n        # detected date column) validate; no random split, no leakage\n        _split = max(2, int(n * 0.75))\n        itr = np.arange(_split)\n        iva = np.arange(_split, n)\n        est = _safe_fit(_wrap_multi(make_estimator(SEED)), X_all[itr], y_fit[itr])\n        va = predict(est, X_all[iva])\n        for k, j in enumerate(iva):\n            _record(j, y_all[j], va[k])\n        final = make_estimator(SEED + 7)\n        final = _safe_fit(_wrap_multi(final), X_all, y_fit)\n        return predict(final, X_test)\n    if VALIDATION == \"single_holdout\":\n        _ts = min(0.5, max(0.25, 2.0 / max(1, n)))\n        itr, iva = _holdout_split(_ts, SEED,\n                                  y_all if is_classification and n_classes > 1\n                                  else None)\n        est = _safe_fit(_wrap_multi(make_estimator(SEED)), X_all[itr], y_fit[itr])\n        va = predict(est, X_all[iva])\n        if _MULTI_PROBA:\n            for k, j in enumerate(iva):\n                _record(j, y_all[j], va[k])\n        else:\n            for k, j in enumerate(iva):\n                _record(j, y_all[j], va[k])\n        final = make_estimator(SEED + 7)\n        final = _safe_fit(_wrap_multi(final), X_all, y_fit)\n        return predict(final, X_test)\n    folds = max(1, int(PARAMS.get(\"folds\", 5)))\n    if n // folds < 2:\n        folds = 1\n    if folds < 2:\n        # Too few rows for K-fold: use a single 50/50 holdout so the OOF\n        # contract still has at least one validation row (sklearn KFold\n        # requires n_splits >= 2).\n        _tr, _va = _holdout_split(0.5, SEED,\n                                 y_all if is_classification and n_classes > 1\n                                 else None)\n        _est = _safe_fit(_wrap_multi(make_estimator(SEED)), X_all[_tr], y_fit[_tr])\n        _va_pred = predict(_est, X_all[_va])\n        if _MULTI_PROBA:\n            for _k, _j in enumerate(_va):\n                _record(_j, y_all[_j], _va_pred[_k])\n        else:\n            for _k, _j in enumerate(_va):\n                _record(_j, y_all[_j], _va_pred[_k])\n        final = make_estimator(SEED + 7)\n        final = _safe_fit(_wrap_multi(final), X_all, y_fit)\n        return predict(final, X_test)\n    if is_classification and n_classes > 1:\n        try:\n            from sklearn.model_selection import StratifiedKFold\n            splitter = StratifiedKFold(n_splits=folds, shuffle=True, random_state=SEED)\n        except ValueError:\n            # A rare class with a single member cannot be stratified:\n            # fall back to plain KFold (generic safety net).\n            from sklearn.model_selection import KFold\n            splitter = KFold(n_splits=folds, shuffle=True, random_state=SEED)\n    else:\n        from sklearn.model_selection import KFold\n        splitter = KFold(n_splits=folds, shuffle=True, random_state=SEED)\n    for tr_idx, va_idx in splitter.split(X_all, y_all):\n        est = _safe_fit(_wrap_multi(make_estimator(SEED)), X_all[tr_idx], y_fit[tr_idx])\n        va = predict(est, X_all[va_idx])\n        if _MULTI_PROBA:\n            for k, j in enumerate(va_idx):\n                _record(j, y_all[j], va[k])\n        else:\n            for k, j in enumerate(va_idx):\n                _record(j, y_all[j], va[k])\n    final = make_estimator(SEED + 7)\n    final = _safe_fit(_wrap_multi(final), X_all, y_fit)\n    return predict(final, X_test)\n\ndef _constant_run(constant):\n    for j in range(n):\n        _record(j, y_all[j], constant)\n    m = len(df_test)\n    if _MULTI_PROBA:\n        out = np.zeros((m, n_classes))\n        ci = classes_.index(str(constant)) if str(constant) in classes_ else 0\n        out[:, ci] = 1.0\n        return out\n    if MULTI_TARGET:\n        try:\n            cv = float(constant)\n        except (TypeError, ValueError):\n            cv = 0.0\n        return np.full((m, len(TARGET_COLS)), cv)\n    return np.array([constant] * m)\n\ndef _fmt(v):\n    try:\n        f = float(v)\n        if math.isnan(f) or math.isinf(f):\n            return \"0.0\"\n        return \"%.9f\" % f\n    except (TypeError, ValueError):\n        return str(v)\n\ndef _is_num(v):\n    try:\n        float(v)\n        return True\n    except (TypeError, ValueError):\n        return False\n\nif (is_classification and n_classes < 2) or (not is_classification and len(y_all) < 2):\n    if is_classification:\n        _const = classes_[0] if n_classes == 1 else \"0\"\n    else:\n        _nums = [float(v) for v in y_all if _is_num(v)]\n        _const = repr(round(float(np.mean(_nums)), 6)) if _nums else \"0.0\"\n    test_out = _constant_run(_const)\nelse:\n    test_out = _run_cv()\n\n# ---------------------------------------------------------------- artifacts\ndef _write_oof():\n    with open(\"oof.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh)\n        if _MULTI_PROBA:\n            hdr = [\"true\"]\n            if METRIC_NAME == \"kl_div\":\n                hdr += [\"true_%s\" % c for c in classes_]\n            hdr += [\"pred_%s\" % c for c in classes_]\n            w.writerow(hdr)\n            for j in oof_order:\n                row = [oof_true_by_idx[j]]\n                if METRIC_NAME == \"kl_div\":\n                    row += [\"1\" if oof_true_by_idx[j] == c else \"0\" for c in classes_]\n                row += [_fmt(v) for v in oof_mat[j]]\n                w.writerow(row)\n        else:\n            w.writerow([\"true\", \"pred\"])\n            for j in oof_order:\n                w.writerow([oof_true_by_idx[j], _fmt(oof_vec_by_idx[j])])\n    log(\"oof.csv rows=%d\" % len(oof_order))\n\ndef _class_of(pred):\n    if _MULTI_PROBA:\n        return str(classes_[int(np.argmax(np.asarray(pred)))])\n    return str(pred)\n\ndef _norm_proba_row(vals, n_cols):\n    \"\"\"Generic probability-row repair: clip to [0,1] and renormalize\n    to sum 1.0 so the submission always passes official atol=1e-6\n    row-sum checks.\"\"\"\n    a = np.asarray([max(0.0, float(v)) for v in vals], dtype=\"float64\")\n    s = a.sum()\n    if s <= 0.0 or not np.isfinite(s):\n        return np.full(n_cols, 1.0 / max(1, n_cols))\n    return a / s\n\ndef _prob_for_class(pred, cname):\n    try:\n        if _MULTI_PROBA:\n            idx = classes_.index(str(cname))\n            return _fmt(pred[idx])\n        if _BINARY_PROBA:\n            return _fmt(pred)\n    except (ValueError, IndexError, TypeError):\n        pass\n    return \"0.0\"\n\ndef _sniff_newline(path):\n    \"\"\"Match the sample\'s line terminator so submission.csv is byte-identical\n    to sample_submission.csv on any OS (Linux LF vs Windows CRLF).\"\"\"\n    try:\n        if path and os.path.isfile(path):\n            with open(path, \"rb\") as fh:\n                chunk = fh.read(8192)\n            if b\"\\r\\n\" in chunk:\n                return \"\\r\\n\"\n            if b\"\\n\" in chunk:\n                return \"\\n\"\n            if b\"\\r\" in chunk:\n                return \"\\r\"\n    except OSError:\n        pass\n    return \"\\r\\n\"\n\ndef _write_submission(test_out):\n    pred_cols = SAMPLE_OUTPUT if SAMPLE_OUTPUT else [TARGET_COL]\n    passthrough = SAMPLE_PASSTHROUGH if SAMPLE_PASSTHROUGH else [id_col]\n    # v2.5.5: join predictions on ALL passthrough columns (id-only for\n    # standard tasks, Date+Comment for no-id tasks) and write rows in\n    # sample-header order, so a target-first sample (Insult,Date,Comment)\n    # emits target then passthroughs exactly as the grader expects.\n    test_key_to_idx = {}\n    if SYN_COLS:\n        _kvals = df_test[SYN_COLS[0]].astype(str).str.strip()\n        for _c in SYN_COLS[1:]:\n            _kvals = _kvals + \"_\" + df_test[_c].astype(str).str.strip()\n        for _ri, _k in enumerate(_kvals.values):\n            test_key_to_idx.setdefault(str(_k), _ri)\n    else:\n        for _ri in range(len(df_test)):\n            _rk = tuple(str(df_test[c].astype(str).iloc[_ri]) for c in passthrough)\n            test_key_to_idx.setdefault(_rk, _ri)\n    if sample_header:\n        rows = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        records = rows.to_dict(\"records\")\n    else:\n        records = [dict(zip(passthrough, [str(v) for v in r])) for r in test_ids]\n    with open(\"submission.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col] + pred_cols)\n        for rec in records:\n            if SYN_COLS:\n                _rk = str(rec.get(_SYN_ID_COL, \"\")).strip()\n            else:\n                _rk = tuple(str(rec.get(c, \"\")) for c in passthrough)\n            i = test_key_to_idx.get(_rk, 0)\n            pred = test_out[i] if i < len(test_out) else test_out[0]\n            pred_vals = {}\n            if len(pred_cols) == 1:\n                __c = pred_cols[0]\n                if _MULTI_PROBA or not is_classification or _BINARY_PROBA:\n                    if _BINARY_PROBA:\n                        pred_vals[__c] = _fmt(pred)\n                    elif _MULTI_PROBA:\n                        pred_vals[__c] = _class_of(pred)\n                    else:\n                        pred_vals[__c] = _fmt(pred)\n                else:\n                    pred_vals[__c] = _class_of(pred)\n            else:\n                if _MULTI_PROBA:\n                    vals = [_prob_for_class(pred, cname) for cname in pred_cols]\n                    norm = _norm_proba_row(vals, len(pred_cols))\n                    for _c, _v in zip(pred_cols, norm):\n                        pred_vals[_c] = _fmt(_v)\n                elif _BINARY_PROBA:\n                    for _c in pred_cols:\n                        pred_vals[_c] = _prob_for_class(pred, _c)\n                elif MULTI_TARGET:\n                    for _c, _pv in zip(pred_cols,\n                                       np.asarray(pred, dtype=\"float64\").reshape(-1)):\n                        pred_vals[_c] = _fmt(_pv)\n                else:\n                    label = _class_of(pred)\n                    for _c in pred_cols:\n                        pred_vals[_c] = \"1\" if str(_c) == str(label) else \"0\"\n            row = [str(rec.get(cname, \"\"))\n                   if (cname in passthrough or cname == _SYN_ID_COL)\n                   else pred_vals.get(cname, \"\")\n                   for cname in (sample_header if sample_header\n                                 else passthrough + pred_cols)]\n            w.writerow(row)\n    log(\"submission.csv rows=%d cols=%s\" % (len(records), pred_cols))\n\n_write_oof()\n_write_submission(test_out)\nlog(\"done wall=%.1fs\" % (time.time() - T0))'

_IMAGE_EMBED_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3 ProgramCompiler deterministic render (image embedding head).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\nimport torch\n\ndef log(msg):\n    print(\"[compiled] %s\" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get(\"TRAIN_CSV\") or \"train.csv\"\nTEST_CSV = os.environ.get(\"TEST_CSV\") or \"test.csv\"\nSAMPLE_SUB = os.environ.get(\"SAMPLE_SUBMISSION\") or \"\"\nTARGET_COL = (os.environ.get(\"TARGET_COLUMN\") or \"\").strip()\nTASK_TYPE = (os.environ.get(\"TASK_TYPE\") or \"classification\").lower()\nTRAIN_IMAGES = os.environ.get(\"TRAIN_IMAGES\") or \"\"\nTEST_IMAGES = os.environ.get(\"TEST_IMAGES\") or \"\"\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nPREPROC = json.loads(\'@@PREPROCESSING_JSON@@\')\nVALIDATION = \'@@VALIDATION@@\'\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nMETRIC_KIND = \'@@METRIC_KIND@@\'\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get(\"val_seed\", 42))\nIMAGE_SIZE = int(PARAMS.get(\"image_size\", 128))\nMODEL_NAME = str(PARAMS.get(\"model_name\", \"efficientnet_b0\"))\nBATCH = int(PARAMS.get(\"batch_size\", 64))\nDEVICE = \"cuda\" if torch.cuda.is_available() else \"cpu\"\nrandom.seed(SEED)\nnp.random.seed(SEED)\ntorch.manual_seed(SEED)\nlog(\"device=%s model=%s size=%d\" % (DEVICE, MODEL_NAME, IMAGE_SIZE))\n\ndf_train = pd.read_csv(TRAIN_CSV)\ndf_test = pd.read_csv(TEST_CSV)\n\n# ------------------------------------------------------------------ id column\nsample_header = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    try:\n        sample_header = [str(c) for c in pd.read_csv(SAMPLE_SUB, nrows=0).columns]\n    except Exception:\n        sample_header = []\n# v2.5.5: sample passthrough = sample-submission columns that exist in\n# test.csv (in sample order); the FIRST passthrough column is the join id.\n# Handles no-id sample headers (target first, e.g. Insult,Date,Comment) -\n# sample column 0 is never assumed to be the id.\nSAMPLE_PASSTHROUGH = [str(c) for c in sample_header if str(c) in df_test.columns]\nSAMPLE_OUTPUT = [str(c) for c in sample_header if str(c) not in df_test.columns]\nid_col = SAMPLE_PASSTHROUGH[0] if SAMPLE_PASSTHROUGH else None\nif id_col is None or id_col not in df_test.columns:\n    id_col = next((c for c in (\"id\", \"Id\", \"ID\", \"index\") if c in df_test.columns), None)\nif id_col is None or id_col not in df_test.columns:\n    id_col = str(df_test.columns[0])\nSAMPLE_TARGETS = [str(c) for c in sample_header\n                  if str(c) not in df_test.columns\n                  and str(c) in df_train.columns]\nif not TARGET_COL or TARGET_COL not in df_train.columns:\n    cands = [str(c) for c in df_train.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df_train.columns[-1])\ny_all = df_train[TARGET_COL].astype(str).values\ntest_ids = df_test[id_col].astype(str).values\nn = len(df_train)\nis_classification = TASK_TYPE == \"classification\"\nclasses_ = sorted(set(y_all)) if is_classification else []\nn_classes = len(classes_)\n\n# ------------------------------------------------------------- cached arrays\n_IMG_EXTS = (\".png\", \".jpg\", \".jpeg\", \".bmp\", \".tif\", \".tiff\", \".webp\")\n\ndef _csv_ids(csv_path):\n    import csv as _csv\n    with open(csv_path, newline=\"\", encoding=\"utf-8\", errors=\"replace\") as fh:\n        rows = list(_csv.reader(fh))\n    hdr = [str(h) for h in (rows[0] if rows else [])]\n    col = id_col if id_col in hdr else (hdr[0] if hdr else None)\n    if col is None:\n        raise RuntimeError(\"compiled: no id column in \" + csv_path)\n    idx = hdr.index(col)\n    return [str(r[idx]) for r in rows[1:] if len(r) > idx]\n\ndef _decode_one(img_id, img_dir):\n    base = os.path.join(img_dir, str(img_id))\n    if not os.path.isfile(base):\n        for ext in _IMG_EXTS:\n            cand = base + ext\n            if os.path.isfile(cand):\n                base = cand\n                break\n    if not os.path.isfile(base):\n        return None\n    from PIL import Image\n    img = Image.open(base).convert(\"RGB\")\n    return np.asarray(img, dtype=np.uint8)\n\ndef load_arrays(kind):\n    cache_dirs = json.loads(os.environ.get(\"V2_CACHE_DIRS\") or \"{}\")\n    sizes = sorted((int(k) for k in cache_dirs), reverse=True)\n    chosen = None\n    for s in sizes:\n        if s <= IMAGE_SIZE:\n            chosen = str(s)\n            break\n    if chosen is None and sizes:\n        chosen = str(sizes[0])\n    if chosen:\n        d = cache_dirs[chosen]\n        xp = os.path.join(d, kind + \"_X.npy\")\n        X = None\n        try:\n            X = np.load(xp, mmap_mode=\"r\")\n        except (OSError, ValueError) as _e:\n            log(\"cache unreadable size=%s (%s): raw decode fallback\"\n                % (chosen, str(_e)[:100]))\n        if X is not None:\n            csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n            ids = _csv_ids(csv_path)\n            ids_json = os.path.join(d, kind + \"_ids.json\")\n            cache_ids = []\n            if os.path.isfile(ids_json):\n                try:\n                    cache_ids = json.loads(open(ids_json, encoding=\"utf-8\").read())\n                except Exception:\n                    cache_ids = []\n            if len(X) == len(ids) and (not cache_ids or cache_ids == ids):\n                log(\"cache hit size=%s kind=%s rows=%d\" % (chosen, kind, len(X)))\n                return X\n            log(\"cache mismatch (rows %d/%d ids %d/%d): raw decode fallback\"\n                % (len(X), len(ids), len(cache_ids), len(ids)))\n    csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n    img_dir = TRAIN_IMAGES if kind == \"train\" else TEST_IMAGES\n    ids = _csv_ids(csv_path)\n    arr = np.zeros((len(ids), IMAGE_SIZE, IMAGE_SIZE, 3), dtype=np.uint8)\n    for i, iid in enumerate(ids):\n        dec = _decode_one(iid, img_dir)\n        if dec is None:\n            continue\n        from PIL import Image\n        dec = np.asarray(Image.fromarray(dec).resize((IMAGE_SIZE, IMAGE_SIZE)),\n                         dtype=np.uint8)\n        arr[i] = dec\n    log(\"raw decode kind=%s rows=%d\" % (kind, len(ids)))\n    return arr\n\nX_train = load_arrays(\"train\")\nX_test = load_arrays(\"test\")\n\n# ------------------------------------------------------------ backbone\ndef _tv_features(model, x):\n    import torch.nn as nn\n    if hasattr(model, \"forward_features\"):\n        return model.forward_features(x)\n    body = nn.Sequential(*list(model.children())[:-1])\n    f = body(x)\n    if f.ndim > 2:\n        f = f.mean(dim=(2, 3))\n    return f\n\ndef load_backbone():\n    try:\n        import timm\n        m = timm.create_model(MODEL_NAME, pretrained=True, num_classes=0)\n        log(\"backbone=timm pretrained=1\")\n        return m, \"timm\"\n    except Exception as e1:\n        log(\"timm failed (%s); torchvision fallback\" % str(e1)[:100])\n        import torchvision.models as tvm\n        try:\n            m = getattr(tvm, MODEL_NAME)(weights=\"DEFAULT\")\n        except Exception:\n            m = getattr(tvm, MODEL_NAME)(weights=None)\n            log(\"backbone=torchvision pretrained=0 (no cached weights)\")\n        return m, \"torchvision\"\n\nmodel, backend = load_backbone()\nmodel.eval()\nmodel.to(DEVICE)\n\ndef _norm(x):\n    if \"imagenet_norm\" in PREPROC:\n        mean = torch.tensor([0.485, 0.456, 0.406], device=x.device).view(1, 3, 1, 1)\n        std = torch.tensor([0.229, 0.224, 0.225], device=x.device).view(1, 3, 1, 1)\n        return (x / 255.0 - mean) / std\n    return x / 255.0\n\n@torch.no_grad()\ndef embed(model, X, batch):\n    out = []\n    for s in range(0, len(X), batch):\n        x = torch.from_numpy(np.asarray(X[s:s + batch])).permute(0, 3, 1, 2).float()\n        x = _norm(x).to(DEVICE)\n        f = model(x) if backend == \"timm\" else _tv_features(model, x)\n        out.append(f.detach().cpu().numpy())\n    if not out:\n        return np.zeros((0, 1))\n    feats = np.vstack(out)\n    if feats.ndim > 2:\n        feats = feats.reshape(feats.shape[0], -1)\n    return feats\n\nlog(\"embedding train...\")\nE_train = embed(model, X_train, BATCH)\nlog(\"embedding test...\")\nE_test = embed(model, X_test, BATCH)\ndel model\nif torch.cuda.is_available():\n    torch.cuda.empty_cache()\nlog(\"embed dim=%d\" % E_train.shape[1])\n\n# ----------------------------------------------------------- row cap (hint)\nsel_idx = np.arange(n)\nif MAX_TRAIN_ROWS > 0 and n > MAX_TRAIN_ROWS:\n    if is_classification and n_classes > 1:\n        from sklearn.model_selection import train_test_split\n        _sel, _ = train_test_split(np.arange(n), train_size=int(MAX_TRAIN_ROWS),\n                                   random_state=SEED, stratify=y_all)\n        sel_idx = np.sort(_sel)\n    else:\n        _rng = np.random.RandomState(SEED)\n        sel_idx = np.sort(_rng.choice(n, size=int(MAX_TRAIN_ROWS), replace=False))\n    E_all = E_train[sel_idx]\n    y_sel = y_all[sel_idx]\n    n_sel = len(y_sel)\nelse:\n    E_all = E_train\n    y_sel = y_all\n    n_sel = n\n\n# ------------------------------------------------------------ sklearn head\ndef make_estimator(seed):\n    _C = float(PARAMS.get(\"C\", 1.0))\n    _mi = int(PARAMS.get(\"max_iter\", 1000))\n    if is_classification:\n        from sklearn.linear_model import LogisticRegression\n        return LogisticRegression(C=_C, max_iter=_mi, solver=\"lbfgs\",\n                                  n_jobs=1, random_state=seed)\n    from sklearn.linear_model import Ridge\n    return Ridge(alpha=max(1e-6, 1.0 / _C), random_state=seed)\n\n_BINARY_PROBA = is_classification and n_classes == 2 and \\\n    METRIC_NAME in (\"auc\", \"binary_logloss\")\n_MULTI_PROBA = METRIC_KIND == \"proba\" and is_classification and not _BINARY_PROBA\n\ndef predict(est, X):\n    if _MULTI_PROBA:\n        P = est.predict_proba(X)\n        if P.shape[1] != len(classes_) or list(est.classes_) != classes_:\n            P2 = np.zeros((P.shape[0], len(classes_)))\n            cls = [str(c) for c in est.classes_]\n            for i, c in enumerate(cls):\n                if c in classes_:\n                    P2[:, classes_.index(c)] = P[:, i]\n            return P2\n        return P\n    if _BINARY_PROBA:\n        P = est.predict_proba(X)\n        return P[:, 1] if P.shape[1] == 2 else P[:, 0]\n    return est.predict(X)\n\n# ------------------------------------------------------------------ CV + OOF\noof_order = []\noof_true_by_idx = {}\noof_vec_by_idx = {}\noof_mat = None\nif _MULTI_PROBA:\n    oof_mat = np.full((n_sel, n_classes), np.nan)\n\ndef _record(j, true_v, pred_v):\n    oof_order.append(int(j))\n    oof_true_by_idx[int(j)] = str(true_v)\n    if oof_mat is not None:\n        oof_mat[int(j)] = np.asarray(pred_v, dtype=\"float64\")\n    else:\n        oof_vec_by_idx[int(j)] = pred_v\n\ndef _run_cv():\n    if VALIDATION == \"single_holdout\":\n        from sklearn.model_selection import train_test_split\n        _args = dict(test_size=0.25, random_state=SEED)\n        if is_classification and n_classes > 1:\n            _args[\"stratify\"] = y_sel\n        itr, iva = train_test_split(np.arange(n_sel), **_args)\n        est = make_estimator(SEED)\n        est.fit(E_all[itr], y_sel[itr])\n        va = predict(est, E_all[iva])\n        for k, j in enumerate(iva):\n            _record(j, y_sel[j], va[k])\n        final = make_estimator(SEED + 7)\n        final.fit(E_all, y_sel)\n        return predict(final, E_test)\n    folds = max(1, int(PARAMS.get(\"folds\", 3)))\n    if n_sel // folds < 2:\n        folds = 1\n    if is_classification and n_classes > 1:\n        from sklearn.model_selection import StratifiedKFold\n        splitter = StratifiedKFold(n_splits=folds, shuffle=True, random_state=SEED)\n    else:\n        from sklearn.model_selection import KFold\n        splitter = KFold(n_splits=folds, shuffle=True, random_state=SEED)\n    for tr_idx, va_idx in splitter.split(E_all, y_sel):\n        est = make_estimator(SEED)\n        est.fit(E_all[tr_idx], y_sel[tr_idx])\n        va = predict(est, E_all[va_idx])\n        for k, j in enumerate(va_idx):\n            _record(j, y_sel[j], va[k])\n    final = make_estimator(SEED + 7)\n    final.fit(E_all, y_sel)\n    return predict(final, E_test)\n\ndef _is_num(v):\n    try:\n        float(v)\n        return True\n    except (TypeError, ValueError):\n        return False\n\ndef _constant_run(constant):\n    for j in range(n_sel):\n        _record(j, y_sel[j], constant)\n    m = len(E_test)\n    if _MULTI_PROBA:\n        out = np.zeros((m, n_classes))\n        ci = classes_.index(str(constant)) if str(constant) in classes_ else 0\n        out[:, ci] = 1.0\n        return out\n    return np.array([constant] * m)\n\ndef _fmt(v):\n    try:\n        f = float(v)\n        if math.isnan(f) or math.isinf(f):\n            return \"0.0\"\n        return \"%.9f\" % f\n    except (TypeError, ValueError):\n        return str(v)\n\nif (is_classification and n_classes < 2) or (not is_classification and len(y_sel) < 2):\n    if is_classification:\n        _const = classes_[0] if n_classes == 1 else \"0\"\n    else:\n        _nums = [float(v) for v in y_sel if _is_num(v)]\n        _const = repr(round(float(np.mean(_nums)), 6)) if _nums else \"0.0\"\n    test_out = _constant_run(_const)\nelse:\n    test_out = _run_cv()\n\n# ---------------------------------------------------------------- artifacts\ndef _write_oof():\n    with open(\"oof.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh)\n        if _MULTI_PROBA:\n            hdr = [\"true\"]\n            if METRIC_NAME == \"kl_div\":\n                hdr += [\"true_%s\" % c for c in classes_]\n            hdr += [\"pred_%s\" % c for c in classes_]\n            w.writerow(hdr)\n            for j in oof_order:\n                row = [oof_true_by_idx[j]]\n                if METRIC_NAME == \"kl_div\":\n                    row += [\"1\" if oof_true_by_idx[j] == c else \"0\" for c in classes_]\n                row += [_fmt(v) for v in oof_mat[j]]\n                w.writerow(row)\n        else:\n            w.writerow([\"true\", \"pred\"])\n            for j in oof_order:\n                w.writerow([oof_true_by_idx[j], _fmt(oof_vec_by_idx[j])])\n    log(\"oof.csv rows=%d\" % len(oof_order))\n\ndef _class_of(pred):\n    if _MULTI_PROBA:\n        return str(classes_[int(np.argmax(np.asarray(pred)))])\n    return str(pred)\n\ndef _norm_proba_row(vals, n_cols):\n    \"\"\"Generic probability-row repair: clip to [0,1] and renormalize\n    to sum 1.0 so the submission always passes official atol=1e-6\n    row-sum checks.\"\"\"\n    a = np.asarray([max(0.0, float(v)) for v in vals], dtype=\"float64\")\n    s = a.sum()\n    if s <= 0.0 or not np.isfinite(s):\n        return np.full(n_cols, 1.0 / max(1, n_cols))\n    return a / s\n\ndef _prob_for_class(pred, cname):\n    try:\n        if _MULTI_PROBA:\n            idx = classes_.index(str(cname))\n            return _fmt(pred[idx])\n        if _BINARY_PROBA:\n            return _fmt(pred)\n    except (ValueError, IndexError, TypeError):\n        pass\n    return \"0.0\"\n\ndef _sniff_newline(path):\n    \"\"\"Match the sample\'s line terminator so submission.csv is byte-identical\n    to sample_submission.csv on any OS (Linux LF vs Windows CRLF).\"\"\"\n    try:\n        if path and os.path.isfile(path):\n            with open(path, \"rb\") as fh:\n                chunk = fh.read(8192)\n            if b\"\\r\\n\" in chunk:\n                return \"\\r\\n\"\n            if b\"\\n\" in chunk:\n                return \"\\n\"\n            if b\"\\r\" in chunk:\n                return \"\\r\"\n    except OSError:\n        pass\n    return \"\\r\\n\"\n\ndef _write_submission(test_out):\n    pred_cols = SAMPLE_OUTPUT if SAMPLE_OUTPUT else [TARGET_COL]\n    passthrough = SAMPLE_PASSTHROUGH if SAMPLE_PASSTHROUGH else [id_col]\n    # v2.5.5: join predictions on ALL passthrough columns (id-only for\n    # standard tasks, Date+Comment for no-id tasks) and write rows in\n    # sample-header order, so a target-first sample (Insult,Date,Comment)\n    # emits target then passthroughs exactly as the grader expects.\n    test_key_to_idx = {}\n    for _ri in range(len(df_test)):\n        _rk = tuple(str(df_test[c].astype(str).iloc[_ri]) for c in passthrough)\n        test_key_to_idx.setdefault(_rk, _ri)\n    if sample_header:\n        rows = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        records = rows.to_dict(\"records\")\n    else:\n        records = [dict(zip(passthrough, [str(v) for v in r])) for r in test_ids]\n    with open(\"submission.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col] + pred_cols)\n        for rec in records:\n            _rk = tuple(str(rec.get(c, \"\")) for c in passthrough)\n            i = test_key_to_idx.get(_rk, 0)\n            pred = test_out[i] if i < len(test_out) else test_out[0]\n            pred_vals = {}\n            if len(pred_cols) == 1:\n                __c = pred_cols[0]\n                if _BINARY_PROBA:\n                    pred_vals[__c] = _fmt(pred)\n                elif _MULTI_PROBA:\n                    pred_vals[__c] = _class_of(pred)\n                elif is_classification:\n                    pred_vals[__c] = _class_of(pred)\n                else:\n                    pred_vals[__c] = _fmt(pred)\n            else:\n                if _MULTI_PROBA:\n                    vals = [_prob_for_class(pred, cname) for cname in pred_cols]\n                    norm = _norm_proba_row(vals, len(pred_cols))\n                    for _c, _v in zip(pred_cols, norm):\n                        pred_vals[_c] = _fmt(_v)\n                elif _BINARY_PROBA:\n                    for _c in pred_cols:\n                        pred_vals[_c] = _prob_for_class(pred, _c)\n                else:\n                    label = _class_of(pred)\n                    for _c in pred_cols:\n                        pred_vals[_c] = \"1\" if str(_c) == str(label) else \"0\"\n            row = [str(rec.get(cname, \"\")) if cname in passthrough\n                   else pred_vals.get(cname, \"\")\n                   for cname in (sample_header if sample_header\n                                 else passthrough + pred_cols)]\n            w.writerow(row)\n    log(\"submission.csv rows=%d cols=%s\" % (len(records), pred_cols))\n\n_write_oof()\n_write_submission(test_out)\nlog(\"done wall=%.1fs\" % (time.time() - T0))'

_IMAGE_FINETUNE_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3 ProgramCompiler deterministic render (image fine-tune).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\n\ndef log(msg):\n    print(\"[compiled] %s\" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get(\"TRAIN_CSV\") or \"train.csv\"\nTEST_CSV = os.environ.get(\"TEST_CSV\") or \"test.csv\"\nSAMPLE_SUB = os.environ.get(\"SAMPLE_SUBMISSION\") or \"\"\nTARGET_COL = (os.environ.get(\"TARGET_COLUMN\") or \"\").strip()\nTASK_TYPE = (os.environ.get(\"TASK_TYPE\") or \"classification\").lower()\nTRAIN_IMAGES = os.environ.get(\"TRAIN_IMAGES\") or \"\"\nTEST_IMAGES = os.environ.get(\"TEST_IMAGES\") or \"\"\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nPREPROC = json.loads(\'@@PREPROCESSING_JSON@@\')\nVALIDATION = \'@@VALIDATION@@\'\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nMETRIC_KIND = \'@@METRIC_KIND@@\'\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get(\"val_seed\", 42))\nIMAGE_SIZE = int(PARAMS.get(\"image_size\", 128))\nMODEL_NAME = str(PARAMS.get(\"model_name\", \"efficientnet_b0\"))\nEPOCHS = int(PARAMS.get(\"epochs\", 4))\nLR = float(PARAMS.get(\"lr\", 3e-4))\nBATCH = int(PARAMS.get(\"batch_size\", 32))\nWD = float(PARAMS.get(\"weight_decay\", 1e-4))\nPATIENCE = int(PARAMS.get(\"early_stop_patience\", 2))\nDEVICE = \"cuda\" if torch.cuda.is_available() else \"cpu\"\nrandom.seed(SEED)\nnp.random.seed(SEED)\ntorch.manual_seed(SEED)\nlog(\"device=%s model=%s size=%d epochs=%d\" % (DEVICE, MODEL_NAME, IMAGE_SIZE, EPOCHS))\n\ndf_train = pd.read_csv(TRAIN_CSV)\ndf_test = pd.read_csv(TEST_CSV)\n\n# ------------------------------------------------------------------ id column\nsample_header = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    try:\n        sample_header = [str(c) for c in pd.read_csv(SAMPLE_SUB, nrows=0).columns]\n    except Exception:\n        sample_header = []\n# v2.5.5: sample passthrough = sample-submission columns that exist in\n# test.csv (in sample order); the FIRST passthrough column is the join id.\n# Handles no-id sample headers (target first, e.g. Insult,Date,Comment) -\n# sample column 0 is never assumed to be the id.\nSAMPLE_PASSTHROUGH = [str(c) for c in sample_header if str(c) in df_test.columns]\nSAMPLE_OUTPUT = [str(c) for c in sample_header if str(c) not in df_test.columns]\nid_col = SAMPLE_PASSTHROUGH[0] if SAMPLE_PASSTHROUGH else None\nif id_col is None or id_col not in df_test.columns:\n    id_col = next((c for c in (\"id\", \"Id\", \"ID\", \"index\") if c in df_test.columns), None)\nif id_col is None or id_col not in df_test.columns:\n    id_col = str(df_test.columns[0])\nSAMPLE_TARGETS = [str(c) for c in sample_header\n                  if str(c) not in df_test.columns\n                  and str(c) in df_train.columns]\nif not TARGET_COL or TARGET_COL not in df_train.columns:\n    cands = [str(c) for c in df_train.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df_train.columns[-1])\ny_all = df_train[TARGET_COL].astype(str).values\ntest_ids = df_test[id_col].astype(str).values\nn = len(df_train)\nis_classification = TASK_TYPE == \"classification\"\nclasses_ = sorted(set(y_all)) if is_classification else []\nn_classes = len(classes_)\nif is_classification and n_classes < 2:\n    n_classes = 2  # torch head needs >=2 outputs; degenerate handled below\n\n# ------------------------------------------------------------- cached arrays\n_IMG_EXTS = (\".png\", \".jpg\", \".jpeg\", \".bmp\", \".tif\", \".tiff\", \".webp\")\n\ndef _csv_ids(csv_path):\n    import csv as _csv\n    with open(csv_path, newline=\"\", encoding=\"utf-8\", errors=\"replace\") as fh:\n        rows = list(_csv.reader(fh))\n    hdr = [str(h) for h in (rows[0] if rows else [])]\n    col = id_col if id_col in hdr else (hdr[0] if hdr else None)\n    if col is None:\n        raise RuntimeError(\"compiled: no id column in \" + csv_path)\n    idx = hdr.index(col)\n    return [str(r[idx]) for r in rows[1:] if len(r) > idx]\n\ndef _decode_one(img_id, img_dir):\n    base = os.path.join(img_dir, str(img_id))\n    if not os.path.isfile(base):\n        for ext in _IMG_EXTS:\n            cand = base + ext\n            if os.path.isfile(cand):\n                base = cand\n                break\n    if not os.path.isfile(base):\n        return None\n    from PIL import Image\n    img = Image.open(base).convert(\"RGB\")\n    return np.asarray(img, dtype=np.uint8)\n\ndef load_arrays(kind):\n    cache_dirs = json.loads(os.environ.get(\"V2_CACHE_DIRS\") or \"{}\")\n    sizes = sorted((int(k) for k in cache_dirs), reverse=True)\n    chosen = None\n    for s in sizes:\n        if s <= IMAGE_SIZE:\n            chosen = str(s)\n            break\n    if chosen is None and sizes:\n        chosen = str(sizes[0])\n    if chosen:\n        d = cache_dirs[chosen]\n        xp = os.path.join(d, kind + \"_X.npy\")\n        X = None\n        try:\n            X = np.load(xp, mmap_mode=\"r\")\n        except (OSError, ValueError) as _e:\n            log(\"cache unreadable size=%s (%s): raw decode fallback\"\n                % (chosen, str(_e)[:100]))\n        if X is not None:\n            csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n            ids = _csv_ids(csv_path)\n            ids_json = os.path.join(d, kind + \"_ids.json\")\n            cache_ids = []\n            if os.path.isfile(ids_json):\n                try:\n                    cache_ids = json.loads(open(ids_json, encoding=\"utf-8\").read())\n                except Exception:\n                    cache_ids = []\n            if len(X) == len(ids) and (not cache_ids or cache_ids == ids):\n                log(\"cache hit size=%s kind=%s rows=%d\" % (chosen, kind, len(X)))\n                return X\n            log(\"cache mismatch (rows %d/%d ids %d/%d): raw decode fallback\"\n                % (len(X), len(ids), len(cache_ids), len(ids)))\n    csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n    img_dir = TRAIN_IMAGES if kind == \"train\" else TEST_IMAGES\n    ids = _csv_ids(csv_path)\n    arr = np.zeros((len(ids), IMAGE_SIZE, IMAGE_SIZE, 3), dtype=np.uint8)\n    for i, iid in enumerate(ids):\n        dec = _decode_one(iid, img_dir)\n        if dec is None:\n            continue\n        from PIL import Image\n        dec = np.asarray(Image.fromarray(dec).resize((IMAGE_SIZE, IMAGE_SIZE)),\n                         dtype=np.uint8)\n        arr[i] = dec\n    log(\"raw decode kind=%s rows=%d\" % (kind, len(ids)))\n    return arr\n\nX_train = load_arrays(\"train\")\nX_test = load_arrays(\"test\")\n\n# ------------------------------------------------------------- model factory\ndef build_model(out_dim):\n    try:\n        import timm\n        m = timm.create_model(MODEL_NAME, pretrained=True, num_classes=0)\n        in_feats = m.num_features\n        head = nn.Linear(in_feats, out_dim)\n        m.reset_classifier(0)\n        log(\"backbone=timm pretrained=1\")\n        return m, head\n    except Exception as e1:\n        log(\"timm failed (%s); torchvision fallback\" % str(e1)[:100])\n        import torchvision.models as tvm\n        try:\n            body = getattr(tvm, MODEL_NAME)(weights=\"DEFAULT\")\n        except Exception:\n            body = getattr(tvm, MODEL_NAME)(weights=None)\n            log(\"backbone=torchvision pretrained=0\")\n        if hasattr(body, \"fc\"):\n            in_feats = body.fc.in_features\n            body.fc = nn.Identity()\n        elif hasattr(body, \"classifier\"):\n            in_feats = body.classifier[-1].in_features\n            body.classifier = nn.Identity()\n        else:\n            in_feats = 512\n        return body, nn.Linear(in_feats, out_dim)\n\ndef _augment(x):\n    if \"flip_augment\" in PREPROC and random.random() < 0.5:\n        return torch.flip(x, dims=[3])\n    return x\n\ndef _norm(x):\n    if \"imagenet_norm\" in PREPROC:\n        mean = torch.tensor([0.485, 0.456, 0.406], device=x.device).view(1, 3, 1, 1)\n        std = torch.tensor([0.229, 0.224, 0.225], device=x.device).view(1, 3, 1, 1)\n        return (x / 255.0 - mean) / std\n    return x / 255.0\n\ndef _tensor(X, idxs):\n    x = torch.from_numpy(np.asarray(X[idxs])).permute(0, 3, 1, 2).float()\n    return _norm(x).to(DEVICE)\n\ndef _fit(model, head, X, y, idxs, epochs, val_idx=None, yval=None):\n    params = list(head.parameters()) + list(model.parameters())\n    opt = torch.optim.Adam(params, lr=LR, weight_decay=WD)\n    if is_classification:\n        loss_fn = nn.CrossEntropyLoss()\n    else:\n        loss_fn = nn.MSELoss()\n    ynum = None\n    if is_classification:\n        ynum = np.array([classes_.index(str(v)) for v in y])\n    else:\n        ynum = np.array([float(v) for v in y])\n    best = None\n    best_state = None\n    best_epoch = 0\n    no_improve = 0\n    for ep in range(1, int(epochs) + 1):\n        model.train()\n        head.train()\n        order = list(idxs)\n        random.shuffle(order)\n        tot = 0.0\n        nb = 0\n        for s in range(0, len(order), BATCH):\n            bi = order[s:s + BATCH]\n            xb = _tensor(X, bi)\n            if \"flip_augment\" in PREPROC:\n                xb = _augment(xb)\n            yb = torch.from_numpy(ynum[bi]).to(DEVICE)\n            out = head(model(xb))\n            if not is_classification:\n                out = out.view(-1)\n            loss = loss_fn(out, yb)\n            opt.zero_grad()\n            loss.backward()\n            opt.step()\n            tot += float(loss) * len(bi)\n            nb += len(bi)\n        log(\"epoch %d/%d loss=%.4f\" % (ep, epochs, tot / max(1, nb)))\n        if val_idx is not None and len(val_idx):\n            score = _eval_score(model, head, X, yval, val_idx)\n            if best is None or (score > best if is_classification else score < best):\n                best = score\n                best_epoch = ep\n                best_state = _copy_state(model, head)\n                no_improve = 0\n            else:\n                no_improve += 1\n                if no_improve >= int(PATIENCE):\n                    log(\"early stop at epoch %d\" % ep)\n                    break\n    if best_state is not None:\n        _restore_state(model, head, best_state)\n        log(\"best epoch=%d\" % best_epoch)\n    return model, head\n\ndef _copy_state(model, head):\n    return (model.state_dict(), head.state_dict())\n\ndef _restore_state(model, head, st):\n    model.load_state_dict(st[0])\n    head.load_state_dict(st[1])\n\n@torch.no_grad()\ndef _eval_score(model, head, X, y, idxs):\n    model.eval()\n    head.eval()\n    preds = []\n    for s in range(0, len(idxs), BATCH):\n        bi = idxs[s:s + BATCH]\n        xb = _tensor(X, bi)\n        out = head(model(xb))\n        preds.append(out.detach().cpu().numpy())\n    P = np.vstack(preds)\n    if is_classification:\n        pred_cls = np.argmax(P, axis=1)\n        true_cls = np.array([classes_.index(str(v)) for v in y])\n        return float(np.mean(pred_cls == true_cls))\n    pred_num = P.reshape(-1)\n    true_num = np.array([float(v) for v in y])\n    return float(np.sqrt(np.mean((pred_num - true_num) ** 2)))\n\n@torch.no_grad()\ndef _predict(model, head, X, idxs):\n    model.eval()\n    head.eval()\n    out = []\n    for s in range(0, len(idxs), BATCH):\n        bi = idxs[s:s + BATCH]\n        xb = _tensor(X, bi)\n        out.append(head(model(xb)).detach().cpu().numpy())\n    return np.vstack(out)\n\n# -------------------------------------------------------------- run\n_holdout = None\nif VALIDATION == \"single_holdout\" or True:\n    from sklearn.model_selection import train_test_split\n    _args = dict(test_size=0.2, random_state=SEED)\n    if is_classification and len(classes_) > 1:\n        _args[\"stratify\"] = y_all\n    itr, iva = train_test_split(np.arange(n), **_args)\n    _holdout = (itr, iva)\n\nout_dim = n_classes if is_classification else 1\nmodel, head = build_model(out_dim)\nmodel.to(DEVICE)\nhead.to(DEVICE)\nyva = y_all[_holdout[1]]\n_fit(model, head, X_train, y_all, _holdout[0], EPOCHS,\n     val_idx=_holdout[1], yval=yva)\nlog(\"holdout score (val)\")\n_val_score = _eval_score(model, head, X_train, yva, _holdout[1])\nlog(\"val %s=%.4f\" % (\"acc\" if is_classification else \"rmse\", _val_score))\nP_va = _predict(model, head, X_train, _holdout[1])\nP_te = _predict(model, head, X_test, np.arange(len(X_test)))\n\nis_classification_run = is_classification\nclasses_run = classes_\nn_classes_run = len(classes_run)\n_BINARY_PROBA = is_classification_run and n_classes_run == 2 and \\\n    METRIC_NAME in (\"auc\", \"binary_logloss\")\n_MULTI_PROBA = METRIC_KIND == \"proba\" and is_classification_run and not _BINARY_PROBA\n\ndef _fmt(v):\n    try:\n        f = float(v)\n        if math.isnan(f) or math.isinf(f):\n            return \"0.0\"\n        return \"%.9f\" % f\n    except (TypeError, ValueError):\n        return str(v)\n\ndef _to_pred_vector(P, idxs):\n    \"\"\"P: (m, out_dim) logits -> per-row prediction per contract.\"\"\"\n    if _MULTI_PROBA:\n        ex = np.exp(P - P.max(axis=1, keepdims=True))\n        return ex / ex.sum(axis=1, keepdims=True)\n    if _BINARY_PROBA:\n        if P.shape[1] == 2:\n            ex = np.exp(P - P.max(axis=1, keepdims=True))\n            pr = ex / ex.sum(axis=1, keepdims=True)\n            return pr[:, 1]\n        return 1.0 / (1.0 + np.exp(-P[:, 0]))\n    if is_classification_run:\n        return np.array([str(classes_run[int(np.argmax(r))]) for r in P])\n    return P.reshape(-1)\n\nva_pred = _to_pred_vector(P_va, _holdout[1])\nte_pred = _to_pred_vector(P_te, np.arange(len(X_test)))\n\n# ---------------------------------------------------------------- artifacts\noof_order = []\noof_true_by_idx = {}\noof_vec_by_idx = {}\noof_mat = None\nif _MULTI_PROBA:\n    oof_mat = np.full((len(_holdout[1]), len(classes_run)), np.nan)\n    for k, j in enumerate(_holdout[1]):\n        oof_mat[k] = np.asarray(va_pred[k], dtype=\"float64\")\n        oof_order.append(k)\n        oof_true_by_idx[k] = str(y_all[j])\nelse:\n    for k, j in enumerate(_holdout[1]):\n        oof_vec_by_idx[k] = va_pred[k]\n        oof_order.append(k)\n        oof_true_by_idx[k] = str(y_all[j])\n\ndef _write_oof():\n    with open(\"oof.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh)\n        if _MULTI_PROBA:\n            hdr = [\"true\"]\n            if METRIC_NAME == \"kl_div\":\n                hdr += [\"true_%s\" % c for c in classes_run]\n            hdr += [\"pred_%s\" % c for c in classes_run]\n            w.writerow(hdr)\n            for k in oof_order:\n                row = [oof_true_by_idx[k]]\n                if METRIC_NAME == \"kl_div\":\n                    row += [\"1\" if oof_true_by_idx[k] == c else \"0\" for c in classes_run]\n                row += [_fmt(v) for v in oof_mat[k]]\n                w.writerow(row)\n        else:\n            w.writerow([\"true\", \"pred\"])\n            for k in oof_order:\n                w.writerow([oof_true_by_idx[k], _fmt(oof_vec_by_idx[k])])\n    log(\"oof.csv rows=%d\" % len(oof_order))\n\ndef _class_of(pred):\n    if _MULTI_PROBA:\n        return str(classes_run[int(np.argmax(np.asarray(pred)))])\n    return str(pred)\n\ndef _norm_proba_row(vals, n_cols):\n    \"\"\"Generic probability-row repair: clip to [0,1] and renormalize\n    to sum 1.0 so the submission always passes official atol=1e-6\n    row-sum checks.\"\"\"\n    a = np.asarray([max(0.0, float(v)) for v in vals], dtype=\"float64\")\n    s = a.sum()\n    if s <= 0.0 or not np.isfinite(s):\n        return np.full(n_cols, 1.0 / max(1, n_cols))\n    return a / s\n\ndef _prob_for_class(pred, cname):\n    try:\n        if _MULTI_PROBA:\n            idx = classes_run.index(str(cname))\n            return _fmt(pred[idx])\n        if _BINARY_PROBA:\n            return _fmt(pred)\n    except (ValueError, IndexError, TypeError):\n        pass\n    return \"0.0\"\n\ndef _sniff_newline(path):\n    \"\"\"Match the sample\'s line terminator so submission.csv is byte-identical\n    to sample_submission.csv on any OS (Linux LF vs Windows CRLF).\"\"\"\n    try:\n        if path and os.path.isfile(path):\n            with open(path, \"rb\") as fh:\n                chunk = fh.read(8192)\n            if b\"\\r\\n\" in chunk:\n                return \"\\r\\n\"\n            if b\"\\n\" in chunk:\n                return \"\\n\"\n            if b\"\\r\" in chunk:\n                return \"\\r\"\n    except OSError:\n        pass\n    return \"\\r\\n\"\n\ndef _write_submission():\n    pred_cols = SAMPLE_OUTPUT if SAMPLE_OUTPUT else [TARGET_COL]\n    passthrough = SAMPLE_PASSTHROUGH if SAMPLE_PASSTHROUGH else [id_col]\n    # v2.5.5: join predictions on ALL passthrough columns (id-only for\n    # standard tasks, Date+Comment for no-id tasks) and write rows in\n    # sample-header order, so a target-first sample (Insult,Date,Comment)\n    # emits target then passthroughs exactly as the grader expects.\n    test_key_to_idx = {}\n    for _ri in range(len(df_test)):\n        _rk = tuple(str(df_test[c].astype(str).iloc[_ri]) for c in passthrough)\n        test_key_to_idx.setdefault(_rk, _ri)\n    if sample_header:\n        rows = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        records = rows.to_dict(\"records\")\n    else:\n        records = [dict(zip(passthrough, [str(v) for v in r])) for r in test_ids]\n    with open(\"submission.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col] + pred_cols)\n        for rec in records:\n            _rk = tuple(str(rec.get(c, \"\")) for c in passthrough)\n            i = test_key_to_idx.get(_rk, 0)\n            pred = te_pred[i] if i < len(te_pred) else te_pred[0]\n            pred_vals = {}\n            if len(pred_cols) == 1:\n                __c = pred_cols[0]\n                if _BINARY_PROBA:\n                    pred_vals[__c] = _fmt(pred)\n                elif _MULTI_PROBA:\n                    pred_vals[__c] = _class_of(pred)\n                elif is_classification_run:\n                    pred_vals[__c] = _class_of(pred)\n                else:\n                    pred_vals[__c] = _fmt(pred)\n            else:\n                if _MULTI_PROBA:\n                    vals = [_prob_for_class(pred, cname) for cname in pred_cols]\n                    norm = _norm_proba_row(vals, len(pred_cols))\n                    for _c, _v in zip(pred_cols, norm):\n                        pred_vals[_c] = _fmt(_v)\n                elif _BINARY_PROBA:\n                    for _c in pred_cols:\n                        pred_vals[_c] = _prob_for_class(pred, _c)\n                else:\n                    label = _class_of(pred)\n                    for _c in pred_cols:\n                        pred_vals[_c] = \"1\" if str(_c) == str(label) else \"0\"\n            row = [str(rec.get(cname, \"\")) if cname in passthrough\n                   else pred_vals.get(cname, \"\")\n                   for cname in (sample_header if sample_header\n                                 else passthrough + pred_cols)]\n            w.writerow(row)\n    log(\"submission.csv rows=%d cols=%s\" % (len(records), pred_cols))\n\n_write_oof()\n_write_submission()\nlog(\"done wall=%.1fs\" % (time.time() - T0))'

_IMAGE_FINETUNE_V2_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3.9 ProgramCompiler deterministic render (image fine-tune, pretrained-first).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\n\ndef log(msg):\n    print(\"[compiled] %s\" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get(\"TRAIN_CSV\") or \"train.csv\"\nTEST_CSV = os.environ.get(\"TEST_CSV\") or \"test.csv\"\nSAMPLE_SUB = os.environ.get(\"SAMPLE_SUBMISSION\") or \"\"\nTARGET_COL = (os.environ.get(\"TARGET_COLUMN\") or \"\").strip()\nTASK_TYPE = (os.environ.get(\"TASK_TYPE\") or \"classification\").lower()\nTRAIN_IMAGES = os.environ.get(\"TRAIN_IMAGES\") or \"\"\nTEST_IMAGES = os.environ.get(\"TEST_IMAGES\") or \"\"\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nPREPROC = json.loads(\'@@PREPROCESSING_JSON@@\')\nVALIDATION = \'@@VALIDATION@@\'\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nMETRIC_KIND = \'@@METRIC_KIND@@\'\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get(\"val_seed\", 42))\nIMAGE_SIZE = int(PARAMS.get(\"image_size\", 224))\nMODEL_NAME = str(PARAMS.get(\"model_name\", \"efficientnet_b0\"))\nBATCH = int(PARAMS.get(\"batch_size\", 32))\nEPOCHS = int(PARAMS.get(\"epochs\", 6))\nLR = float(PARAMS.get(\"lr\", 3e-4))\nWD = float(PARAMS.get(\"weight_decay\", 1e-4))\nPATIENCE = int(PARAMS.get(\"early_stop_patience\", 3))\nLR_SCHEDULE = str(PARAMS.get(\"lr_schedule\", \"cosine\"))\nAUGMENT = str(PARAMS.get(\"augment\", \"flip\"))\nAMP = bool(PARAMS.get(\"amp\", True))\nTTA_FLIP = bool(PARAMS.get(\"tta_flip\", True))\nLABEL_SMOOTHING = float(PARAMS.get(\"label_smoothing\", 0.0))\nDEVICE = \"cuda\" if torch.cuda.is_available() else \"cpu\"\nrandom.seed(SEED)\nnp.random.seed(SEED)\ntorch.manual_seed(SEED)\nlog(\"device=%s model=%s size=%d epochs=%d amp=%s aug=%s tta=%s\"\n    % (DEVICE, MODEL_NAME, IMAGE_SIZE, EPOCHS, AMP, AUGMENT, TTA_FLIP))\n\ndf_train = pd.read_csv(TRAIN_CSV)\ndf_test = pd.read_csv(TEST_CSV)\n\n# ------------------------------------------------------------------ id column\nsample_header = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    try:\n        sample_header = [str(c) for c in pd.read_csv(SAMPLE_SUB, nrows=0).columns]\n    except Exception:\n        sample_header = []\n# v2.5.5: sample passthrough = sample-submission columns that exist in\n# test.csv (in sample order); the FIRST passthrough column is the join id.\n# Handles no-id sample headers (target first, e.g. Insult,Date,Comment) -\n# sample column 0 is never assumed to be the id.\nSAMPLE_PASSTHROUGH = [str(c) for c in sample_header if str(c) in df_test.columns]\nSAMPLE_OUTPUT = [str(c) for c in sample_header if str(c) not in df_test.columns]\nid_col = SAMPLE_PASSTHROUGH[0] if SAMPLE_PASSTHROUGH else None\nif id_col is None or id_col not in df_test.columns:\n    id_col = next((c for c in (\"id\", \"Id\", \"ID\", \"index\") if c in df_test.columns), None)\nif id_col is None or id_col not in df_test.columns:\n    id_col = str(df_test.columns[0])\nSAMPLE_TARGETS = [str(c) for c in sample_header\n                  if str(c) not in df_test.columns\n                  and str(c) in df_train.columns]\nif not TARGET_COL or TARGET_COL not in df_train.columns:\n    cands = [str(c) for c in df_train.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df_train.columns[-1])\ny_all = df_train[TARGET_COL].astype(str).values\ntest_ids = df_test[id_col].astype(str).values\nn = len(df_train)\nis_classification = TASK_TYPE == \"classification\"\nclasses_ = sorted(set(y_all)) if is_classification else []\nn_classes = len(classes_)\nif MAX_TRAIN_ROWS and n > MAX_TRAIN_ROWS:\n    keep = np.random.RandomState(SEED).choice(n, MAX_TRAIN_ROWS, replace=False)\n    y_all = y_all[keep]\n    df_train = df_train.iloc[keep].reset_index(drop=True)\n    n = len(df_train)\n\n# ------------------------------------------------------------- cached arrays\n_IMG_EXTS = (\".png\", \".jpg\", \".jpeg\", \".bmp\", \".tif\", \".tiff\", \".webp\")\n\ndef _csv_ids(csv_path):\n    import csv as _csv\n    with open(csv_path, newline=\"\", encoding=\"utf-8\", errors=\"replace\") as fh:\n        rows = list(_csv.reader(fh))\n    hdr = [str(h) for h in (rows[0] if rows else [])]\n    col = id_col if id_col in hdr else (hdr[0] if hdr else None)\n    if col is None:\n        raise RuntimeError(\"compiled: no id column in \" + csv_path)\n    idx = hdr.index(col)\n    return [str(r[idx]) for r in rows[1:] if len(r) > idx]\n\ndef _decode_one(img_id, img_dir):\n    base = os.path.join(img_dir, str(img_id))\n    if not os.path.isfile(base):\n        for ext in _IMG_EXTS:\n            cand = base + ext\n            if os.path.isfile(cand):\n                base = cand\n                break\n    if not os.path.isfile(base):\n        return None\n    from PIL import Image\n    img = Image.open(base).convert(\"RGB\")\n    return np.asarray(img, dtype=np.uint8)\n\ndef load_arrays(kind):\n    cache_dirs = json.loads(os.environ.get(\"V2_CACHE_DIRS\") or \"{}\")\n    sizes = sorted((int(k) for k in cache_dirs), reverse=True)\n    chosen = None\n    for s in sizes:\n        if s <= IMAGE_SIZE:\n            chosen = str(s)\n            break\n    if chosen is None and sizes:\n        chosen = str(sizes[0])\n    if chosen:\n        d = cache_dirs[chosen]\n        xp = os.path.join(d, kind + \"_X.npy\")\n        X = None\n        try:\n            X = np.load(xp, mmap_mode=\"r\")\n        except (OSError, ValueError) as _e:\n            log(\"cache unreadable size=%s (%s): raw decode fallback\"\n                % (chosen, str(_e)[:100]))\n        if X is not None:\n            csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n            ids = _csv_ids(csv_path)\n            ids_json = os.path.join(d, kind + \"_ids.json\")\n            cache_ids = []\n            if os.path.isfile(ids_json):\n                try:\n                    cache_ids = json.loads(open(ids_json, encoding=\"utf-8\").read())\n                except Exception:\n                    cache_ids = []\n            if len(X) == len(ids) and (not cache_ids or cache_ids == ids):\n                log(\"cache hit size=%s kind=%s rows=%d\" % (chosen, kind, len(X)))\n                return X\n            log(\"cache mismatch (rows %d/%d ids %d/%d): raw decode fallback\"\n                % (len(X), len(ids), len(cache_ids), len(ids)))\n    csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n    ids = _csv_ids(csv_path)\n    img_dir = TRAIN_IMAGES if kind == \"train\" else TEST_IMAGES\n    if not img_dir:\n        raise RuntimeError(\"compiled: no image dir for \" + kind)\n    arr = np.zeros((len(ids), IMAGE_SIZE, IMAGE_SIZE, 3), dtype=np.uint8)\n    from PIL import Image\n    for k, iid in enumerate(ids):\n        dec = _decode_one(iid, img_dir)\n        if dec is None:\n            continue\n        im = Image.fromarray(dec).resize((IMAGE_SIZE, IMAGE_SIZE),\n                                          Image.BILINEAR)\n        arr[k] = np.asarray(im, dtype=np.uint8)\n    log(\"raw decode kind=%s rows=%d\" % (kind, len(ids)))\n    return arr\n\nX_train = load_arrays(\"train\")\nX_test = load_arrays(\"test\")\n\n# ------------------------------------------------------------- model factory\ndef build_model(out_dim):\n    try:\n        import timm\n        m = timm.create_model(MODEL_NAME, pretrained=True, num_classes=0)\n        in_feats = m.num_features\n        head = nn.Linear(in_feats, out_dim)\n        m.reset_classifier(0)\n        log(\"backbone=timm pretrained=1\")\n        return m, head\n    except Exception as e1:\n        log(\"timm failed (%s); torchvision fallback\" % str(e1)[:100])\n        import torchvision.models as tvm\n        try:\n            body = getattr(tvm, MODEL_NAME)(weights=\"DEFAULT\")\n        except Exception:\n            body = getattr(tvm, MODEL_NAME)(weights=None)\n            log(\"backbone=torchvision pretrained=0\")\n        if hasattr(body, \"fc\"):\n            in_feats = body.fc.in_features\n            body.fc = nn.Identity()\n        elif hasattr(body, \"classifier\"):\n            in_feats = body.classifier[-1].in_features\n            body.classifier = nn.Identity()\n        else:\n            in_feats = 512\n        return body, nn.Linear(in_feats, out_dim)\n\n# ------------------------------------------------------------- preprocessing\ndef _norm(x):\n    if \"imagenet_norm\" in PREPROC:\n        mean = torch.tensor([0.485, 0.456, 0.406], device=x.device).view(1, 3, 1, 1)\n        std = torch.tensor([0.229, 0.224, 0.225], device=x.device).view(1, 3, 1, 1)\n        return (x / 255.0 - mean) / std\n    return x / 255.0\n\ndef _aug_np(a):\n    \"\"\"Augment one uint8 image (H,W,3) -> uint8. Generic content-shape\n    transforms (flip / random resized crop / color jitter), no labels.\"\"\"\n    from PIL import Image, ImageEnhance\n    if AUGMENT in (\"none\", \"\"):\n        return a\n    im = Image.fromarray(a)\n    if AUGMENT in (\"flip\", \"strong\") and random.random() < 0.5:\n        im = im.transpose(Image.FLIP_LEFT_RIGHT)\n    if AUGMENT in (\"rcrop\", \"strong\") and random.random() < 0.6:\n        s = IMAGE_SIZE\n        scale = random.uniform(0.7, 1.0)\n        cs = max(16, int(s * scale))\n        x0 = random.randint(0, max(0, s - cs))\n        y0 = random.randint(0, max(0, s - cs))\n        im = im.crop((x0, y0, x0 + cs, y0 + cs)).resize((s, s), Image.BILINEAR)\n    if AUGMENT == \"strong\":\n        if random.random() < 0.5:\n            im = ImageEnhance.Brightness(im).enhance(random.uniform(0.8, 1.2))\n        if random.random() < 0.5:\n            im = ImageEnhance.Contrast(im).enhance(random.uniform(0.8, 1.2))\n    return np.asarray(im, dtype=np.uint8)\n\ndef _tensor(X, idxs):\n    if AUGMENT in (\"flip\", \"rcrop\", \"strong\"):\n        xb = np.stack([_aug_np(X[i]) for i in idxs])\n    else:\n        xb = np.asarray(X[idxs])\n    x = torch.from_numpy(xb).permute(0, 3, 1, 2).float()\n    return _norm(x).to(DEVICE)\n\n# ------------------------------------------------------------- training\ndef _fit(model, head, X, y, idxs, epochs, val_idx=None, yval=None, seed=None):\n    if seed is not None:\n        random.seed(seed); np.random.seed(seed); torch.manual_seed(seed)\n    params = list(head.parameters()) + list(model.parameters())\n    opt = torch.optim.AdamW(params, lr=LR, weight_decay=WD)\n    sched = None\n    if LR_SCHEDULE == \"cosine\":\n        try:\n            sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=max(1, int(epochs)))\n        except Exception:\n            sched = None\n    if is_classification:\n        try:\n            loss_fn = nn.CrossEntropyLoss(label_smoothing=LABEL_SMOOTHING)\n        except TypeError:\n            loss_fn = nn.CrossEntropyLoss()\n    else:\n        loss_fn = nn.MSELoss()\n    ynum = None\n    if is_classification:\n        ynum = np.array([classes_.index(str(v)) for v in y])\n    else:\n        ynum = np.array([float(v) for v in y])\n    use_amp = bool(AMP and DEVICE == \"cuda\")\n    scaler = None\n    if use_amp:\n        try:\n            from torch.cuda.amp import GradScaler, autocast\n            scaler = GradScaler()\n            amp_ctx = autocast\n        except Exception:\n            use_amp = False\n    best = None\n    best_state = None\n    best_epoch = 0\n    no_improve = 0\n    for ep in range(1, int(epochs) + 1):\n        model.train()\n        head.train()\n        order = list(idxs)\n        random.shuffle(order)\n        tot = 0.0\n        nb = 0\n        for s in range(0, len(order), BATCH):\n            bi = order[s:s + BATCH]\n            xb = _tensor(X, bi)\n            yb = torch.from_numpy(ynum[bi]).to(DEVICE)\n            if use_amp:\n                with amp_ctx():\n                    out = head(model(xb))\n                    if not is_classification:\n                        out = out.view(-1)\n                    loss = loss_fn(out, yb)\n                opt.zero_grad()\n                scaler.scale(loss).backward()\n                scaler.step(opt)\n                scaler.update()\n            else:\n                out = head(model(xb))\n                if not is_classification:\n                    out = out.view(-1)\n                loss = loss_fn(out, yb)\n                opt.zero_grad()\n                loss.backward()\n                opt.step()\n            tot += float(loss) * len(bi)\n            nb += len(bi)\n        if sched is not None:\n            sched.step()\n        log(\"epoch %d/%d loss=%.4f\" % (ep, epochs, tot / max(1, nb)))\n        if val_idx is not None and len(val_idx):\n            score = _eval_score(model, head, X, yval, val_idx)\n            if best is None or (score > best if is_classification else score < best):\n                best = score\n                best_epoch = ep\n                best_state = _copy_state(model, head)\n                no_improve = 0\n            else:\n                no_improve += 1\n                if no_improve >= int(PATIENCE):\n                    log(\"early stop at epoch %d\" % ep)\n                    break\n    if best_state is not None:\n        _restore_state(model, head, best_state)\n        log(\"best epoch=%d\" % best_epoch)\n    return model, head\n\ndef _copy_state(model, head):\n    return (model.state_dict(), head.state_dict())\n\ndef _restore_state(model, head, st):\n    model.load_state_dict(st[0])\n    head.load_state_dict(st[1])\n\n@torch.no_grad()\ndef _eval_score(model, head, X, y, idxs):\n    model.eval()\n    head.eval()\n    preds = []\n    for s in range(0, len(idxs), BATCH):\n        bi = idxs[s:s + BATCH]\n        xb = _tensor(X, bi)\n        out = head(model(xb))\n        preds.append(out.detach().cpu().numpy())\n    P = np.vstack(preds)\n    if is_classification:\n        pred_cls = np.argmax(P, axis=1)\n        true_cls = np.array([classes_.index(str(v)) for v in y])\n        return float(np.mean(pred_cls == true_cls))\n    pred_num = P.reshape(-1)\n    true_num = np.array([float(v) for v in y])\n    return float(np.sqrt(np.mean((pred_num - true_num) ** 2)))\n\n@torch.no_grad()\ndef _predict(model, head, X, idxs):\n    model.eval()\n    head.eval()\n    out = []\n    for s in range(0, len(idxs), BATCH):\n        bi = idxs[s:s + BATCH]\n        xb = _tensor(X, bi)\n        logits = head(model(xb))\n        if TTA_FLIP and is_classification:\n            logits = logits + head(model(torch.flip(xb, dims=[3])))\n        out.append((logits / (2.0 if TTA_FLIP and is_classification else 1.0))\n                   .detach().cpu().numpy())\n    return np.vstack(out)\n\n# -------------------------------------------------------------- run\n_holdout = None\nif VALIDATION == \"single_holdout\" or True:\n    from sklearn.model_selection import train_test_split\n    _args = dict(test_size=0.2, random_state=SEED)\n    if is_classification and len(classes_) > 1:\n        _args[\"stratify\"] = y_all\n    itr, iva = train_test_split(np.arange(n), **_args)\n    _holdout = (itr, iva)\n\nout_dim = n_classes if is_classification else 1\nmodel, head = build_model(out_dim)\nmodel.to(DEVICE)\nhead.to(DEVICE)\nyva = y_all[_holdout[1]]\n_fit(model, head, X_train, y_all, _holdout[0], EPOCHS,\n     val_idx=_holdout[1], yval=yva, seed=SEED)\nlog(\"holdout score (val)\")\n_val_score = _eval_score(model, head, X_train, yva, _holdout[1])\nlog(\"val %s=%.4f\" % (\"acc\" if is_classification else \"rmse\", _val_score))\nP_va = _predict(model, head, X_train, _holdout[1])\nP_te = _predict(model, head, X_test, np.arange(len(X_test)))\n\nis_classification_run = is_classification\nclasses_run = classes_\nn_classes_run = len(classes_run)\n_BINARY_PROBA = is_classification_run and n_classes_run == 2 and \\\n    METRIC_NAME in (\"auc\", \"binary_logloss\")\n_MULTI_PROBA = METRIC_KIND == \"proba\" and is_classification_run and not _BINARY_PROBA\n\ndef _fmt(v):\n    try:\n        f = float(v)\n        if math.isnan(f) or math.isinf(f):\n            return \"0.0\"\n        return \"%.9f\" % f\n    except (TypeError, ValueError):\n        return str(v)\n\ndef _to_pred_vector(P, idxs):\n    \"\"\"P: (m, out_dim) logits -> per-row prediction per contract.\"\"\"\n    if _MULTI_PROBA:\n        ex = np.exp(P - P.max(axis=1, keepdims=True))\n        return ex / ex.sum(axis=1, keepdims=True)\n    if _BINARY_PROBA:\n        if P.shape[1] == 2:\n            ex = np.exp(P - P.max(axis=1, keepdims=True))\n            pr = ex / ex.sum(axis=1, keepdims=True)\n            return pr[:, 1]\n        return 1.0 / (1.0 + np.exp(-P[:, 0]))\n    if is_classification_run:\n        return np.array([str(classes_run[int(np.argmax(r))]) for r in P])\n    return P.reshape(-1)\n\nva_pred = _to_pred_vector(P_va, _holdout[1])\nte_pred = _to_pred_vector(P_te, np.arange(len(X_test)))\n\n# ---------------------------------------------------------------- artifacts\noof_order = []\noof_true_by_idx = {}\noof_vec_by_idx = {}\noof_mat = None\nif _MULTI_PROBA:\n    oof_mat = np.full((len(_holdout[1]), len(classes_run)), np.nan)\n    for k, j in enumerate(_holdout[1]):\n        oof_mat[k] = np.asarray(va_pred[k], dtype=\"float64\")\n        oof_order.append(k)\n        oof_true_by_idx[k] = str(y_all[j])\nelse:\n    for k, j in enumerate(_holdout[1]):\n        oof_vec_by_idx[k] = va_pred[k]\n        oof_order.append(k)\n        oof_true_by_idx[k] = str(y_all[j])\n\ndef _write_oof():\n    with open(\"oof.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh)\n        if _MULTI_PROBA:\n            hdr = [\"true\"]\n            if METRIC_NAME == \"kl_div\":\n                hdr += [\"true_%s\" % c for c in classes_run]\n            hdr += [\"pred_%s\" % c for c in classes_run]\n            w.writerow(hdr)\n            for k in oof_order:\n                row = [oof_true_by_idx[k]]\n                if METRIC_NAME == \"kl_div\":\n                    row += [\"1\" if oof_true_by_idx[k] == c else \"0\" for c in classes_run]\n                row += [_fmt(v) for v in oof_mat[k]]\n                w.writerow(row)\n        else:\n            w.writerow([\"true\", \"pred\"])\n            for k in oof_order:\n                w.writerow([oof_true_by_idx[k], _fmt(oof_vec_by_idx[k])])\n    log(\"oof.csv rows=%d\" % len(oof_order))\n\ndef _class_of(pred):\n    if _MULTI_PROBA:\n        return str(classes_run[int(np.argmax(np.asarray(pred)))])\n    return str(pred)\n\ndef _norm_proba_row(vals, n_cols):\n    \"\"\"Generic probability-row repair: clip to [0,1] and renormalize to sum\n    1.0 so the submission always passes official atol=1e-6 row-sum checks.\"\"\"\n    a = np.asarray([max(0.0, float(v)) for v in vals], dtype=\"float64\")\n    s = a.sum()\n    if s <= 0.0 or not np.isfinite(s):\n        return np.full(n_cols, 1.0 / max(1, n_cols))\n    return a / s\n\ndef _prob_for_class(pred, cname):\n    try:\n        if _MULTI_PROBA:\n            idx = classes_run.index(str(cname))\n            return _fmt(pred[idx])\n        if _BINARY_PROBA:\n            return _fmt(min(1.0, max(0.0, float(pred))))\n    except (ValueError, IndexError, TypeError):\n        pass\n    return \"0.0\"\n\ndef _sniff_newline(path):\n    \"\"\"Match the sample\'s line terminator so submission.csv is byte-identical\n    to sample_submission.csv on any OS (Linux LF vs Windows CRLF).\"\"\"\n    try:\n        if path and os.path.isfile(path):\n            with open(path, \"rb\") as fh:\n                chunk = fh.read(8192)\n            if b\"\\r\\n\" in chunk:\n                return \"\\r\\n\"\n            if b\"\\n\" in chunk:\n                return \"\\n\"\n            if b\"\\r\" in chunk:\n                return \"\\r\"\n    except OSError:\n        pass\n    return \"\\r\\n\"\n\ndef _write_submission():\n    pred_cols = SAMPLE_OUTPUT if SAMPLE_OUTPUT else [TARGET_COL]\n    passthrough = SAMPLE_PASSTHROUGH if SAMPLE_PASSTHROUGH else [id_col]\n    # v2.5.5: join predictions on ALL passthrough columns (id-only for\n    # standard tasks, Date+Comment for no-id tasks) and write rows in\n    # sample-header order, so a target-first sample (Insult,Date,Comment)\n    # emits target then passthroughs exactly as the grader expects.\n    test_key_to_idx = {}\n    for _ri in range(len(df_test)):\n        _rk = tuple(str(df_test[c].astype(str).iloc[_ri]) for c in passthrough)\n        test_key_to_idx.setdefault(_rk, _ri)\n    if sample_header:\n        rows = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        records = rows.to_dict(\"records\")\n    else:\n        records = [dict(zip(passthrough, [str(v) for v in r])) for r in test_ids]\n    with open(\"submission.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col] + pred_cols)\n        for rec in records:\n            _rk = tuple(str(rec.get(c, \"\")) for c in passthrough)\n            i = test_key_to_idx.get(_rk, 0)\n            pred = te_pred[i] if i < len(te_pred) else te_pred[0]\n            pred_vals = {}\n            if len(pred_cols) == 1:\n                __c = pred_cols[0]\n                if _BINARY_PROBA:\n                    pred_vals[__c] = _prob_for_class(pred, pred_cols[0])\n                elif _MULTI_PROBA:\n                    pred_vals[__c] = _class_of(pred)\n                elif is_classification_run:\n                    pred_vals[__c] = _class_of(pred)\n                else:\n                    pred_vals[__c] = _fmt(pred)\n            else:\n                if _MULTI_PROBA:\n                    vals = [_prob_for_class(pred, cname) for cname in pred_cols]\n                    norm = _norm_proba_row(vals, len(pred_cols))\n                    for _c, _v in zip(pred_cols, norm):\n                        pred_vals[_c] = _fmt(_v)\n                elif _BINARY_PROBA:\n                    for _c in pred_cols:\n                        pred_vals[_c] = _prob_for_class(pred, _c)\n                else:\n                    label = _class_of(pred)\n                    for _c in pred_cols:\n                        pred_vals[_c] = \"1\" if str(_c) == str(label) else \"0\"\n            row = [str(rec.get(cname, \"\")) if cname in passthrough\n                   else pred_vals.get(cname, \"\")\n                   for cname in (sample_header if sample_header\n                                 else passthrough + pred_cols)]\n            w.writerow(row)\n    log(\"submission.csv rows=%d cols=%s\" % (len(records), pred_cols))\n\n_write_oof()\n_write_submission()\nlog(\"done wall=%.1fs\" % (time.time() - T0))'

_IMAGE_FINETUNE_ENSEMBLE_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3.9 ProgramCompiler deterministic render (image fine-tune ENSEMBLE:\n# K models x seeds -> averaged probabilities; generic for any image\n# classification/regression contract, no competition names).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\n\ndef log(msg):\n    print(\"[compiled] %s\" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get(\"TRAIN_CSV\") or \"train.csv\"\nTEST_CSV = os.environ.get(\"TEST_CSV\") or \"test.csv\"\nSAMPLE_SUB = os.environ.get(\"SAMPLE_SUBMISSION\") or \"\"\nTARGET_COL = (os.environ.get(\"TARGET_COLUMN\") or \"\").strip()\nTASK_TYPE = (os.environ.get(\"TASK_TYPE\") or \"classification\").lower()\nTRAIN_IMAGES = os.environ.get(\"TRAIN_IMAGES\") or \"\"\nTEST_IMAGES = os.environ.get(\"TEST_IMAGES\") or \"\"\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nPREPROC = json.loads(\'@@PREPROCESSING_JSON@@\')\nVALIDATION = \'@@VALIDATION@@\'\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nMETRIC_KIND = \'@@METRIC_KIND@@\'\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get(\"val_seed\", 42))\nIMAGE_SIZE = int(PARAMS.get(\"image_size\", 224))\nMODEL_NAMES = [str(m) for m in (PARAMS.get(\"model_names\") or [\"efficientnet_b0\"])][:3]\nSEEDS = [int(s) for s in (PARAMS.get(\"seeds\") or [42])][:2]\nBATCH = int(PARAMS.get(\"batch_size\", 24))\nEPOCHS = int(PARAMS.get(\"epochs\", 6))\nLR = float(PARAMS.get(\"lr\", 3e-4))\nWD = float(PARAMS.get(\"weight_decay\", 1e-4))\nPATIENCE = int(PARAMS.get(\"early_stop_patience\", 3))\nLR_SCHEDULE = str(PARAMS.get(\"lr_schedule\", \"cosine\"))\nAUGMENT = str(PARAMS.get(\"augment\", \"flip\"))\nAMP = bool(PARAMS.get(\"amp\", True))\nTTA_FLIP = bool(PARAMS.get(\"tta_flip\", True))\nLABEL_SMOOTHING = float(PARAMS.get(\"label_smoothing\", 0.0))\nDEVICE = \"cuda\" if torch.cuda.is_available() else \"cpu\"\nrandom.seed(SEED)\nnp.random.seed(SEED)\ntorch.manual_seed(SEED)\nlog(\"device=%s models=%s seeds=%s size=%d epochs=%d amp=%s aug=%s tta=%s\"\n    % (DEVICE, MODEL_NAMES, SEEDS, IMAGE_SIZE, EPOCHS, AMP, AUGMENT, TTA_FLIP))\n\ndf_train = pd.read_csv(TRAIN_CSV)\ndf_test = pd.read_csv(TEST_CSV)\n\n# ------------------------------------------------------------------ id column\nsample_header = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    try:\n        sample_header = [str(c) for c in pd.read_csv(SAMPLE_SUB, nrows=0).columns]\n    except Exception:\n        sample_header = []\n# v2.5.5: sample passthrough = sample-submission columns that exist in\n# test.csv (in sample order); the FIRST passthrough column is the join id.\n# Handles no-id sample headers (target first, e.g. Insult,Date,Comment) -\n# sample column 0 is never assumed to be the id.\nSAMPLE_PASSTHROUGH = [str(c) for c in sample_header if str(c) in df_test.columns]\nSAMPLE_OUTPUT = [str(c) for c in sample_header if str(c) not in df_test.columns]\nid_col = SAMPLE_PASSTHROUGH[0] if SAMPLE_PASSTHROUGH else None\nif id_col is None or id_col not in df_test.columns:\n    id_col = next((c for c in (\"id\", \"Id\", \"ID\", \"index\") if c in df_test.columns), None)\nif id_col is None or id_col not in df_test.columns:\n    id_col = str(df_test.columns[0])\nSAMPLE_TARGETS = [str(c) for c in sample_header\n                  if str(c) not in df_test.columns\n                  and str(c) in df_train.columns]\nif not TARGET_COL or TARGET_COL not in df_train.columns:\n    cands = [str(c) for c in df_train.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df_train.columns[-1])\ny_all = df_train[TARGET_COL].astype(str).values\ntest_ids = df_test[id_col].astype(str).values\nn = len(df_train)\nis_classification = TASK_TYPE == \"classification\"\nclasses_ = sorted(set(y_all)) if is_classification else []\nn_classes = len(classes_)\nif MAX_TRAIN_ROWS and n > MAX_TRAIN_ROWS:\n    keep = np.random.RandomState(SEED).choice(n, MAX_TRAIN_ROWS, replace=False)\n    y_all = y_all[keep]\n    df_train = df_train.iloc[keep].reset_index(drop=True)\n    n = len(df_train)\n\n# ------------------------------------------------------------- cached arrays\n_IMG_EXTS = (\".png\", \".jpg\", \".jpeg\", \".bmp\", \".tif\", \".tiff\", \".webp\")\n\ndef _csv_ids(csv_path):\n    import csv as _csv\n    with open(csv_path, newline=\"\", encoding=\"utf-8\", errors=\"replace\") as fh:\n        rows = list(_csv.reader(fh))\n    hdr = [str(h) for h in (rows[0] if rows else [])]\n    col = id_col if id_col in hdr else (hdr[0] if hdr else None)\n    if col is None:\n        raise RuntimeError(\"compiled: no id column in \" + csv_path)\n    idx = hdr.index(col)\n    return [str(r[idx]) for r in rows[1:] if len(r) > idx]\n\ndef _decode_one(img_id, img_dir):\n    base = os.path.join(img_dir, str(img_id))\n    if not os.path.isfile(base):\n        for ext in _IMG_EXTS:\n            cand = base + ext\n            if os.path.isfile(cand):\n                base = cand\n                break\n    if not os.path.isfile(base):\n        return None\n    from PIL import Image\n    img = Image.open(base).convert(\"RGB\")\n    return np.asarray(img, dtype=np.uint8)\n\ndef load_arrays(kind):\n    cache_dirs = json.loads(os.environ.get(\"V2_CACHE_DIRS\") or \"{}\")\n    sizes = sorted((int(k) for k in cache_dirs), reverse=True)\n    chosen = None\n    for s in sizes:\n        if s <= IMAGE_SIZE:\n            chosen = str(s)\n            break\n    if chosen is None and sizes:\n        chosen = str(sizes[0])\n    if chosen:\n        d = cache_dirs[chosen]\n        xp = os.path.join(d, kind + \"_X.npy\")\n        X = None\n        try:\n            X = np.load(xp, mmap_mode=\"r\")\n        except (OSError, ValueError) as _e:\n            log(\"cache unreadable size=%s (%s): raw decode fallback\"\n                % (chosen, str(_e)[:100]))\n        if X is not None:\n            csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n            ids = _csv_ids(csv_path)\n            ids_json = os.path.join(d, kind + \"_ids.json\")\n            cache_ids = []\n            if os.path.isfile(ids_json):\n                try:\n                    cache_ids = json.loads(open(ids_json, encoding=\"utf-8\").read())\n                except Exception:\n                    cache_ids = []\n            if len(X) == len(ids) and (not cache_ids or cache_ids == ids):\n                log(\"cache hit size=%s kind=%s rows=%d\" % (chosen, kind, len(X)))\n                return X\n            log(\"cache mismatch (rows %d/%d ids %d/%d): raw decode fallback\"\n                % (len(X), len(ids), len(cache_ids), len(ids)))\n    csv_path = TRAIN_CSV if kind == \"train\" else TEST_CSV\n    ids = _csv_ids(csv_path)\n    img_dir = TRAIN_IMAGES if kind == \"train\" else TEST_IMAGES\n    if not img_dir:\n        raise RuntimeError(\"compiled: no image dir for \" + kind)\n    arr = np.zeros((len(ids), IMAGE_SIZE, IMAGE_SIZE, 3), dtype=np.uint8)\n    from PIL import Image\n    for k, iid in enumerate(ids):\n        dec = _decode_one(iid, img_dir)\n        if dec is None:\n            continue\n        im = Image.fromarray(dec).resize((IMAGE_SIZE, IMAGE_SIZE),\n                                          Image.BILINEAR)\n        arr[k] = np.asarray(im, dtype=np.uint8)\n    log(\"raw decode kind=%s rows=%d\" % (kind, len(ids)))\n    return arr\n\nX_train = load_arrays(\"train\")\nX_test = load_arrays(\"test\")\n\n# ------------------------------------------------------------- model factory\ndef build_model(model_name, out_dim):\n    try:\n        import timm\n        m = timm.create_model(model_name, pretrained=True, num_classes=0)\n        in_feats = m.num_features\n        head = nn.Linear(in_feats, out_dim)\n        m.reset_classifier(0)\n        log(\"backbone=%s timm pretrained=1\" % model_name)\n        return m, head\n    except Exception as e1:\n        log(\"timm failed (%s); torchvision fallback\" % str(e1)[:100])\n        import torchvision.models as tvm\n        try:\n            body = getattr(tvm, model_name)(weights=\"DEFAULT\")\n        except Exception:\n            body = getattr(tvm, model_name)(weights=None)\n            log(\"backbone=%s torchvision pretrained=0\" % model_name)\n        if hasattr(body, \"fc\"):\n            in_feats = body.fc.in_features\n            body.fc = nn.Identity()\n        elif hasattr(body, \"classifier\"):\n            in_feats = body.classifier[-1].in_features\n            body.classifier = nn.Identity()\n        else:\n            in_feats = 512\n        return body, nn.Linear(in_feats, out_dim)\n\n# ------------------------------------------------------------- preprocessing\ndef _norm(x):\n    if \"imagenet_norm\" in PREPROC:\n        mean = torch.tensor([0.485, 0.456, 0.406], device=x.device).view(1, 3, 1, 1)\n        std = torch.tensor([0.229, 0.224, 0.225], device=x.device).view(1, 3, 1, 1)\n        return (x / 255.0 - mean) / std\n    return x / 255.0\n\ndef _aug_np(a):\n    from PIL import Image, ImageEnhance\n    if AUGMENT in (\"none\", \"\"):\n        return a\n    im = Image.fromarray(a)\n    if AUGMENT in (\"flip\", \"strong\") and random.random() < 0.5:\n        im = im.transpose(Image.FLIP_LEFT_RIGHT)\n    if AUGMENT in (\"rcrop\", \"strong\") and random.random() < 0.6:\n        s = IMAGE_SIZE\n        scale = random.uniform(0.7, 1.0)\n        cs = max(16, int(s * scale))\n        x0 = random.randint(0, max(0, s - cs))\n        y0 = random.randint(0, max(0, s - cs))\n        im = im.crop((x0, y0, x0 + cs, y0 + cs)).resize((s, s), Image.BILINEAR)\n    if AUGMENT == \"strong\":\n        if random.random() < 0.5:\n            im = ImageEnhance.Brightness(im).enhance(random.uniform(0.8, 1.2))\n        if random.random() < 0.5:\n            im = ImageEnhance.Contrast(im).enhance(random.uniform(0.8, 1.2))\n    return np.asarray(im, dtype=np.uint8)\n\ndef _tensor(X, idxs):\n    if AUGMENT in (\"flip\", \"rcrop\", \"strong\"):\n        xb = np.stack([_aug_np(X[i]) for i in idxs])\n    else:\n        xb = np.asarray(X[idxs])\n    x = torch.from_numpy(xb).permute(0, 3, 1, 2).float()\n    return _norm(x).to(DEVICE)\n\n# ------------------------------------------------------------- training\ndef _fit(model, head, X, y, idxs, epochs, val_idx=None, yval=None, seed=None):\n    if seed is not None:\n        random.seed(seed); np.random.seed(seed); torch.manual_seed(seed)\n    params = list(head.parameters()) + list(model.parameters())\n    opt = torch.optim.AdamW(params, lr=LR, weight_decay=WD)\n    sched = None\n    if LR_SCHEDULE == \"cosine\":\n        try:\n            sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=max(1, int(epochs)))\n        except Exception:\n            sched = None\n    if is_classification:\n        try:\n            loss_fn = nn.CrossEntropyLoss(label_smoothing=LABEL_SMOOTHING)\n        except TypeError:\n            loss_fn = nn.CrossEntropyLoss()\n    else:\n        loss_fn = nn.MSELoss()\n    ynum = None\n    if is_classification:\n        ynum = np.array([classes_.index(str(v)) for v in y])\n    else:\n        ynum = np.array([float(v) for v in y])\n    use_amp = bool(AMP and DEVICE == \"cuda\")\n    scaler = None\n    if use_amp:\n        try:\n            from torch.cuda.amp import GradScaler, autocast\n            scaler = GradScaler()\n            amp_ctx = autocast\n        except Exception:\n            use_amp = False\n    best = None\n    best_state = None\n    best_epoch = 0\n    no_improve = 0\n    for ep in range(1, int(epochs) + 1):\n        model.train()\n        head.train()\n        order = list(idxs)\n        random.shuffle(order)\n        tot = 0.0\n        nb = 0\n        for s in range(0, len(order), BATCH):\n            bi = order[s:s + BATCH]\n            xb = _tensor(X, bi)\n            yb = torch.from_numpy(ynum[bi]).to(DEVICE)\n            if use_amp:\n                with amp_ctx():\n                    out = head(model(xb))\n                    if not is_classification:\n                        out = out.view(-1)\n                    loss = loss_fn(out, yb)\n                opt.zero_grad()\n                scaler.scale(loss).backward()\n                scaler.step(opt)\n                scaler.update()\n            else:\n                out = head(model(xb))\n                if not is_classification:\n                    out = out.view(-1)\n                loss = loss_fn(out, yb)\n                opt.zero_grad()\n                loss.backward()\n                opt.step()\n            tot += float(loss) * len(bi)\n            nb += len(bi)\n        if sched is not None:\n            sched.step()\n        log(\"epoch %d/%d loss=%.4f\" % (ep, epochs, tot / max(1, nb)))\n        if val_idx is not None and len(val_idx):\n            score = _eval_score(model, head, X, yval, val_idx)\n            if best is None or (score > best if is_classification else score < best):\n                best = score\n                best_epoch = ep\n                best_state = _copy_state(model, head)\n                no_improve = 0\n            else:\n                no_improve += 1\n                if no_improve >= int(PATIENCE):\n                    log(\"early stop at epoch %d\" % ep)\n                    break\n    if best_state is not None:\n        _restore_state(model, head, best_state)\n        log(\"best epoch=%d\" % best_epoch)\n    return model, head\n\ndef _copy_state(model, head):\n    return (model.state_dict(), head.state_dict())\n\ndef _restore_state(model, head, st):\n    model.load_state_dict(st[0])\n    head.load_state_dict(st[1])\n\n@torch.no_grad()\ndef _eval_score(model, head, X, y, idxs):\n    model.eval()\n    head.eval()\n    preds = []\n    for s in range(0, len(idxs), BATCH):\n        bi = idxs[s:s + BATCH]\n        xb = _tensor(X, bi)\n        out = head(model(xb))\n        preds.append(out.detach().cpu().numpy())\n    P = np.vstack(preds)\n    if is_classification:\n        pred_cls = np.argmax(P, axis=1)\n        true_cls = np.array([classes_.index(str(v)) for v in y])\n        return float(np.mean(pred_cls == true_cls))\n    pred_num = P.reshape(-1)\n    true_num = np.array([float(v) for v in y])\n    return float(np.sqrt(np.mean((pred_num - true_num) ** 2)))\n\n@torch.no_grad()\ndef _predict(model, head, X, idxs):\n    model.eval()\n    head.eval()\n    out = []\n    for s in range(0, len(idxs), BATCH):\n        bi = idxs[s:s + BATCH]\n        xb = _tensor(X, bi)\n        logits = head(model(xb))\n        if TTA_FLIP and is_classification:\n            logits = logits + head(model(torch.flip(xb, dims=[3])))\n        out.append((logits / (2.0 if TTA_FLIP and is_classification else 1.0))\n                   .detach().cpu().numpy())\n    return np.vstack(out)\n\n# -------------------------------------------------------------- run\n_holdout = None\nif VALIDATION == \"single_holdout\" or True:\n    from sklearn.model_selection import train_test_split\n    _args = dict(test_size=0.2, random_state=SEED)\n    if is_classification and len(classes_) > 1:\n        _args[\"stratify\"] = y_all\n    itr, iva = train_test_split(np.arange(n), **_args)\n    _holdout = (itr, iva)\n\nout_dim = n_classes if is_classification else 1\nyva = y_all[_holdout[1]]\nn_va = len(_holdout[1])\nn_te = len(X_test)\nsum_va = np.zeros((n_va, out_dim), dtype=\"float64\")\nsum_te = np.zeros((n_te, out_dim), dtype=\"float64\")\ncombos = []\nfor mn in MODEL_NAMES:\n    for sd in SEEDS:\n        combos.append((mn, sd))\n        if len(combos) >= 4:\n            break\n    if len(combos) >= 4:\n        break\nlog(\"ensemble combos=%d %s\" % (len(combos), combos))\nfor ci, (mn, sd) in enumerate(combos, 1):\n    log(\"[member %d/%d] train %s seed=%d\" % (ci, len(combos), mn, sd))\n    model, head = build_model(mn, out_dim)\n    model.to(DEVICE)\n    head.to(DEVICE)\n    _fit(model, head, X_train, y_all, _holdout[0], EPOCHS,\n         val_idx=_holdout[1], yval=yva, seed=sd)\n    mva = _eval_score(model, head, X_train, yva, _holdout[1])\n    log(\"member %d val %s=%.4f\" % (ci, \"acc\" if is_classification else \"rmse\", mva))\n    sum_va += _predict(model, head, X_train, _holdout[1])\n    sum_te += _predict(model, head, X_test, np.arange(n_te))\nP_va = sum_va / len(combos)\nP_te = sum_te / len(combos)\nlog(\"ensemble averaged %d members\" % len(combos))\n\nis_classification_run = is_classification\nclasses_run = classes_\nn_classes_run = len(classes_run)\n_BINARY_PROBA = is_classification_run and n_classes_run == 2 and \\\n    METRIC_NAME in (\"auc\", \"binary_logloss\")\n_MULTI_PROBA = METRIC_KIND == \"proba\" and is_classification_run and not _BINARY_PROBA\n\ndef _fmt(v):\n    try:\n        f = float(v)\n        if math.isnan(f) or math.isinf(f):\n            return \"0.0\"\n        return \"%.9f\" % f\n    except (TypeError, ValueError):\n        return str(v)\n\ndef _to_pred_vector(P, idxs):\n    \"\"\"P: (m, out_dim) logits -> per-row prediction per contract.\"\"\"\n    if _MULTI_PROBA:\n        ex = np.exp(P - P.max(axis=1, keepdims=True))\n        return ex / ex.sum(axis=1, keepdims=True)\n    if _BINARY_PROBA:\n        if P.shape[1] == 2:\n            ex = np.exp(P - P.max(axis=1, keepdims=True))\n            pr = ex / ex.sum(axis=1, keepdims=True)\n            return pr[:, 1]\n        return 1.0 / (1.0 + np.exp(-P[:, 0]))\n    if is_classification_run:\n        return np.array([str(classes_run[int(np.argmax(r))]) for r in P])\n    return P.reshape(-1)\n\nva_pred = _to_pred_vector(P_va, _holdout[1])\nte_pred = _to_pred_vector(P_te, np.arange(len(X_test)))\n\n# ---------------------------------------------------------------- artifacts\noof_order = []\noof_true_by_idx = {}\noof_vec_by_idx = {}\noof_mat = None\nif _MULTI_PROBA:\n    oof_mat = np.full((len(_holdout[1]), len(classes_run)), np.nan)\n    for k, j in enumerate(_holdout[1]):\n        oof_mat[k] = np.asarray(va_pred[k], dtype=\"float64\")\n        oof_order.append(k)\n        oof_true_by_idx[k] = str(y_all[j])\nelse:\n    for k, j in enumerate(_holdout[1]):\n        oof_vec_by_idx[k] = va_pred[k]\n        oof_order.append(k)\n        oof_true_by_idx[k] = str(y_all[j])\n\ndef _write_oof():\n    with open(\"oof.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh)\n        if _MULTI_PROBA:\n            hdr = [\"true\"]\n            if METRIC_NAME == \"kl_div\":\n                hdr += [\"true_%s\" % c for c in classes_run]\n            hdr += [\"pred_%s\" % c for c in classes_run]\n            w.writerow(hdr)\n            for k in oof_order:\n                row = [oof_true_by_idx[k]]\n                if METRIC_NAME == \"kl_div\":\n                    row += [\"1\" if oof_true_by_idx[k] == c else \"0\" for c in classes_run]\n                row += [_fmt(v) for v in oof_mat[k]]\n                w.writerow(row)\n        else:\n            w.writerow([\"true\", \"pred\"])\n            for k in oof_order:\n                w.writerow([oof_true_by_idx[k], _fmt(oof_vec_by_idx[k])])\n    log(\"oof.csv rows=%d\" % len(oof_order))\n\ndef _class_of(pred):\n    if _MULTI_PROBA:\n        return str(classes_run[int(np.argmax(np.asarray(pred)))])\n    return str(pred)\n\ndef _norm_proba_row(vals, n_cols):\n    a = np.asarray([max(0.0, float(v)) for v in vals], dtype=\"float64\")\n    s = a.sum()\n    if s <= 0.0 or not np.isfinite(s):\n        return np.full(n_cols, 1.0 / max(1, n_cols))\n    return a / s\n\ndef _prob_for_class(pred, cname):\n    try:\n        if _MULTI_PROBA:\n            idx = classes_run.index(str(cname))\n            return _fmt(pred[idx])\n        if _BINARY_PROBA:\n            return _fmt(min(1.0, max(0.0, float(pred))))\n    except (ValueError, IndexError, TypeError):\n        pass\n    return \"0.0\"\n\ndef _sniff_newline(path):\n    try:\n        if path and os.path.isfile(path):\n            with open(path, \"rb\") as fh:\n                chunk = fh.read(8192)\n            if b\"\\r\\n\" in chunk:\n                return \"\\r\\n\"\n            if b\"\\n\" in chunk:\n                return \"\\n\"\n            if b\"\\r\" in chunk:\n                return \"\\r\"\n    except OSError:\n        pass\n    return \"\\r\\n\"\n\ndef _write_submission():\n    pred_cols = SAMPLE_OUTPUT if SAMPLE_OUTPUT else [TARGET_COL]\n    passthrough = SAMPLE_PASSTHROUGH if SAMPLE_PASSTHROUGH else [id_col]\n    # v2.5.5: join predictions on ALL passthrough columns (id-only for\n    # standard tasks, Date+Comment for no-id tasks) and write rows in\n    # sample-header order, so a target-first sample (Insult,Date,Comment)\n    # emits target then passthroughs exactly as the grader expects.\n    test_key_to_idx = {}\n    for _ri in range(len(df_test)):\n        _rk = tuple(str(df_test[c].astype(str).iloc[_ri]) for c in passthrough)\n        test_key_to_idx.setdefault(_rk, _ri)\n    if sample_header:\n        rows = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        records = rows.to_dict(\"records\")\n    else:\n        records = [dict(zip(passthrough, [str(v) for v in r])) for r in test_ids]\n    with open(\"submission.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col] + pred_cols)\n        for rec in records:\n            _rk = tuple(str(rec.get(c, \"\")) for c in passthrough)\n            i = test_key_to_idx.get(_rk, 0)\n            pred = te_pred[i] if i < len(te_pred) else te_pred[0]\n            pred_vals = {}\n            if len(pred_cols) == 1:\n                __c = pred_cols[0]\n                if _BINARY_PROBA:\n                    pred_vals[__c] = _prob_for_class(pred, pred_cols[0])\n                elif _MULTI_PROBA:\n                    pred_vals[__c] = _class_of(pred)\n                elif is_classification_run:\n                    pred_vals[__c] = _class_of(pred)\n                else:\n                    pred_vals[__c] = _fmt(pred)\n            else:\n                if _MULTI_PROBA:\n                    vals = [_prob_for_class(pred, cname) for cname in pred_cols]\n                    norm = _norm_proba_row(vals, len(pred_cols))\n                    for _c, _v in zip(pred_cols, norm):\n                        pred_vals[_c] = _fmt(_v)\n                elif _BINARY_PROBA:\n                    for _c in pred_cols:\n                        pred_vals[_c] = _prob_for_class(pred, _c)\n                else:\n                    label = _class_of(pred)\n                    for _c in pred_cols:\n                        pred_vals[_c] = \"1\" if str(_c) == str(label) else \"0\"\n            row = [str(rec.get(cname, \"\")) if cname in passthrough\n                   else pred_vals.get(cname, \"\")\n                   for cname in (sample_header if sample_header\n                                 else passthrough + pred_cols)]\n            w.writerow(row)\n    log(\"submission.csv rows=%d cols=%s\" % (len(records), pred_cols))\n\n_write_oof()\n_write_submission()\nlog(\"done wall=%.1fs\" % (time.time() - T0))'

