_IMAGE_PIXEL_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3.7 ProgramCompiler deterministic render (image-to-image pixel regression baseline).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\n\ndef log(msg):\n    print("[compiled] %s" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get("TRAIN_CSV") or "train.csv"\nSAMPLE_SUB = os.environ.get("SAMPLE_SUBMISSION") or ""\nTARGET_COL = (os.environ.get("TARGET_COLUMN") or "").strip()\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get("val_seed", 42))\nBASIS = str(PARAMS.get("basis", "per_image")).strip().lower()\nrandom.seed(SEED)\nnp.random.seed(SEED)\n\n# ------------------------------------------------------------- train pixels\nif not TARGET_COL:\n    TARGET_COL = "value"\ndf = pd.read_csv(TRAIN_CSV, dtype=str)\nid_col = str(df.columns[0])\nif TARGET_COL not in df.columns:\n    cands = [str(c) for c in df.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df.columns[1])\n\nif MAX_TRAIN_ROWS > 0 and len(df) > MAX_TRAIN_ROWS:\n    df = df.sample(n=MAX_TRAIN_ROWS, random_state=SEED)\ndf["_val"] = pd.to_numeric(df[TARGET_COL], errors="coerce").astype("float64")\ndf = df.dropna(subset=["_val"])\nparts = df[id_col].astype(str).str.rsplit("_", n=2, expand=True)\ndf["_stem"] = parts[0]\ndf["_row"] = pd.to_numeric(parts[1], errors="coerce")\ndf["_col"] = pd.to_numeric(parts[2], errors="coerce")\ndf = df.dropna(subset=["_row", "_col"])\n\n# ------------------------------------------------- image-level holdout (no\n# pixel leakage: neighboring pixels are correlated, so splits are by IMAGE)\nstems = sorted(set(df["_stem"]))\nrandom.shuffle(stems)\nn_val = max(1, int(round(len(stems) * 0.2)))\nval_stems = set(stems[:n_val])\ntrain_df = df[~df["_stem"].isin(val_stems)]\nval_df = df[df["_stem"].isin(val_stems)]\nif len(train_df) == 0:\n    train_df = val_df\n    val_df = val_df.iloc[0:0]\n\nglobal_mean = float(train_df["_val"].mean()) if len(train_df) else 0.5\nper_image = train_df.groupby("_stem")["_val"].mean().to_dict()\nspatial = train_df.groupby(["_row", "_col"])["_val"].mean().to_dict()\n\n\ndef _predict(stem, r, c):\n    if BASIS == "per_image":\n        if stem in per_image:\n            return float(per_image[stem])\n        if (r, c) in spatial:\n            return float(spatial[(r, c)])\n        return global_mean\n    if BASIS == "spatial":\n        if (r, c) in spatial:\n            return float(spatial[(r, c)])\n        if stem in per_image:\n            return float(per_image[stem])\n        return global_mean\n    return global_mean\n\n\ndef _fmt(v):\n    try:\n        f = float(v)\n        if math.isnan(f) or math.isinf(f):\n            return "0.0"\n        return "%.6f" % f\n    except (TypeError, ValueError):\n        return "0.0"\n\n\n# ------------------------------------------------------------------- oof\nif len(val_df):\n    val_pred = np.array([_predict(st, r, c) for st, r, c in\n                         zip(val_df["_stem"], val_df["_row"], val_df["_col"])])\n    val_true = val_df["_val"].astype("float64").values\n    rmse = float(math.sqrt(float(np.mean((val_pred - val_true) ** 2))))\nelse:\n    val_true = np.array([])\n    val_pred = np.array([])\n    rmse = float("nan")\nwith open("oof.csv", "w", newline="", encoding="utf-8") as fh:\n    w = csv.writer(fh)\n    w.writerow(["true", "pred"])\n    for tv, pv in zip(val_true, val_pred):\n        w.writerow([_fmt(tv), _fmt(pv)])\nlog("oof.csv rows=%d" % len(val_true))\nlog("val %s=%.6f" % (METRIC_NAME, rmse))\nlog("rmse: %.6f" % rmse)\n\n# ------------------------------------------------------------- submission\nsample_header = []\nsample_ids = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    with open(SAMPLE_SUB, newline="", encoding="utf-8", errors="replace") as fh:\n        rows = list(csv.reader(fh))\n    if rows:\n        sample_header = rows[0]\n        sample_ids = [str(r[0]) for r in rows[1:] if r]\nif not sample_ids:\n    raise RuntimeError("compiled: sample submission has no id rows")\n\npred_cols = sample_header[1:] if len(sample_header) > 1 else [TARGET_COL]\n\n\ndef _sniff_newline(path):\n    try:\n        if path and os.path.isfile(path):\n            with open(path, "rb") as fh:\n                chunk = fh.read(8192)\n            if b"\\r\\n" in chunk:\n                return "\\r\\n"\n            if b"\\n" in chunk:\n                return "\\n"\n            if b"\\r" in chunk:\n                return "\\r"\n    except OSError:\n        pass\n    return "\\r\\n"\n\n\nwith open("submission.csv", "w", newline="", encoding="utf-8") as fh:\n    w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n    w.writerow(sample_header if sample_header else [id_col, pred_cols[0]])\n    for sid in sample_ids:\n        sp = str(sid).rsplit("_", 2)\n        try:\n            r = int(sp[1])\n            c = int(sp[2])\n        except (ValueError, IndexError):\n            r = c = -1\n        w.writerow([sid, _fmt(_predict(sp[0], r, c))])\nlog("submission.csv rows=%d cols=%s" % (len(sample_ids), pred_cols))\nlog("done wall=%.1fs" % (time.time() - T0))'



_IMAGE_MASK_RLE_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3.8 ProgramCompiler deterministic render (RLE mask baseline: empty or\n# dense masks; image-level holdout OOF; valid RLE submission for every id).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\n\ndef log(msg):\n    print("[compiled] %s" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get("TRAIN_CSV") or "train.csv"\nSAMPLE_SUB = os.environ.get("SAMPLE_SUBMISSION") or ""\nTARGET_COL = (os.environ.get("MASK_TARGET") or os.environ.get("TARGET_COLUMN") or "").strip()\nTRAIN_IMAGES = os.environ.get("TRAIN_IMAGES") or ""\nTEST_IMAGES = os.environ.get("TEST_IMAGES") or ""\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get("val_seed", 42))\nSTRATEGY = str(PARAMS.get("strategy", "empty")).strip().lower()\nMAX_OOF_PIXELS = int(PARAMS.get("max_oof_pixels", 400000) or 400000)\nrandom.seed(SEED)\nnp.random.seed(SEED)\n\nimport pandas as pd\n\ndf = pd.read_csv(TRAIN_CSV, dtype=str)\nid_col = str(df.columns[0])\nif not TARGET_COL or TARGET_COL not in df.columns:\n    cands = [str(c) for c in df.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df.columns[-1])\n\nif MAX_TRAIN_ROWS > 0 and len(df) > MAX_TRAIN_ROWS:\n    df = df.sample(n=MAX_TRAIN_ROWS, random_state=SEED)\ndf = df.dropna(subset=[id_col])\ndf["_id"] = df[id_col].astype(str).str.strip()\ndf["_rle"] = df[TARGET_COL].astype(str).str.strip()\ndf = df[df["_id"] != ""]\n\n# empty marker: contrails uses "-", most others use the empty string\nEMPTY_MARK = "-" if (df["_rle"] == "-").any() else ""\n\n# dims hint columns (uw-madison ships image_height/image_width)\ndef _dims_from_table(row):\n    h = w = 0\n    for name in ("image_height", "height", "rows", "h"):\n        if name in df.columns:\n            try:\n                h = int(float(str(row[name]).strip()))\n                break\n            except (TypeError, ValueError):\n                pass\n    for name in ("image_width", "width", "cols", "w"):\n        if name in df.columns:\n            try:\n                w = int(float(str(row[name]).strip()))\n                break\n            except (TypeError, ValueError):\n                pass\n    if h > 0 and w > 0:\n        return h, w\n    return None\n\ndef _find_image_for(img_id):\n    for base in (TRAIN_IMAGES, TEST_IMAGES):\n        if not base or not os.path.isdir(base):\n            continue\n        # <id>.<ext> anywhere under the image root\n        for dirpath, dirnames, filenames in os.walk(base):\n            for fn in filenames:\n                stem, ext = os.path.splitext(fn)\n                if stem == img_id:\n                    return os.path.join(dirpath, fn)\n            # <id>/ subdir (contrails record dirs hold npy bands)\n            for dn in dirnames:\n                if dn == img_id:\n                    sub = os.path.join(dirpath, dn)\n                    try:\n                        names = sorted(os.listdir(sub))\n                    except OSError:\n                        continue\n                    for fn in names:\n                        if fn.endswith((".npy", ".png", ".jpg", ".jpeg",\n                                        ".tif", ".tiff", ".bmp")):\n                            return os.path.join(sub, fn)\n    return None\n\ndef _image_dims(path):\n    try:\n        if path.endswith(".npy"):\n            arr = np.load(path)\n            if arr.ndim == 2:\n                return int(arr.shape[0]), int(arr.shape[1])\n            if arr.ndim >= 3:\n                return int(arr.shape[0]), int(arr.shape[1])\n        try:\n            from PIL import Image\n            with Image.open(path) as im:\n                return int(im.size[1]), int(im.size[0])\n        except Exception:\n            pass\n        # stdlib fallback: PNG header\n        with open(path, "rb") as fh:\n            head = fh.read(32)\n        if head[:8] == b"\\x89PNG\\r\\n\\x1a\\n" and len(head) >= 24:\n            w = int.from_bytes(head[16:20], "big")\n            h = int.from_bytes(head[20:24], "big")\n            if w > 0 and h > 0:\n                return h, w\n    except Exception:\n        pass\n    return None\n\ndef _rle_max_pos(rle):\n    parts = str(rle).split()\n    mx = 0\n    for i, p in enumerate(parts):\n        if i % 2 == 0:\n            try:\n                mx = max(mx, int(p))\n            except (TypeError, ValueError):\n                pass\n    return mx\n\ndef _dims_for(row):\n    d = _dims_from_table(row)\n    if d is not None:\n        return d\n    img = _find_image_for(str(row["_id"]))\n    if img is not None:\n        d = _image_dims(img)\n        if d is not None:\n            return d\n    mx = _rle_max_pos(str(row["_rle"]))\n    if mx > 0:\n        n = max(64, int(math.ceil(math.sqrt(mx))))\n        return n, n\n    return 256, 256\n\ndef _decode_mask(rle, h, w):\n    mask = np.zeros(h * w, dtype=bool)\n    s = str(rle).strip()\n    if not s or s == "-" or s.lower() in ("nan", "none"):\n        return mask.reshape(h, w)\n    parts = s.split()\n    if len(parts) % 2 != 0:\n        return mask.reshape(h, w)\n    i = 0\n    while i < len(parts):\n        try:\n            start = int(parts[i]) - 1\n            length = int(parts[i + 1])\n        except (TypeError, ValueError):\n            i += 2\n            continue\n        if start < 0 or length <= 0:\n            i += 2\n            continue\n        end = min(start + length, h * w)\n        if start < h * w:\n            mask[start:end] = True\n        i += 2\n    return mask.reshape(h, w)\n\ndef _encode_rle(mask):\n    flat = mask.T.flatten()\n    dots = np.where(flat)[0]\n    runs = []\n    prev = -2\n    for b in dots:\n        if b > prev + 1:\n            runs.extend((int(b) + 1, 0))\n        runs[-1] += 1\n        prev = int(b)\n    return " ".join(str(x) for x in runs)\n\n# ------------------------------------------------------------- holdout\nids = sorted(set(df["_id"]))\nrandom.shuffle(ids)\nn_val = max(1, int(round(len(ids) * 0.2)))\nval_ids = set(ids[:n_val])\nif not val_ids:\n    val_ids = set(ids)\ntr = df[~df["_id"].isin(val_ids)]\nva = df[df["_id"].isin(val_ids)]\nif len(tr) == 0:\n    tr = va\n    va = va.iloc[0:0]\n\n# per-image dims cache\n_dims_cache = {}\ndef _dims(row):\n    key = str(row["_id"])\n    if key not in _dims_cache:\n        _dims_cache[key] = _dims_for(row)\n    return _dims_cache[key]\n\n# ------------------------------------------------------------- OOF\noof_rows = []\nval_metrics = []\nfor _, row in va.iterrows():\n    h, w = _dims(row)\n    true = _decode_mask(str(row["_rle"]), h, w)\n    if STRATEGY == "dense":\n        pred = np.ones_like(true)\n    else:\n        pred = np.zeros_like(true)\n    tf = true.astype(int).flatten()\n    pf = pred.astype(int).flatten()\n    tp = int(np.sum((tf == 1) & (pf == 1)))\n    fp = int(np.sum((tf == 0) & (pf == 1)))\n    fn = int(np.sum((tf == 1) & (pf == 0)))\n    denom = 2 * tp + fp + fn\n    dice = (2.0 * tp / denom) if denom else 1.0\n    val_metrics.append(dice)\n    for t, p in zip(tf, pf):\n        oof_rows.append((t, p))\n\nif oof_rows:\n    stride = max(1, int(math.ceil(len(oof_rows) / float(MAX_OOF_PIXELS))))\n    sampled = oof_rows[::stride]\nelse:\n    sampled = []\nwith open("oof.csv", "w", newline="", encoding="utf-8") as fh:\n    w_csv = csv.writer(fh)\n    w_csv.writerow(["true", "pred"])\n    for t, p in sampled:\n        w_csv.writerow([t, p])\nmetric = float(np.mean(val_metrics)) if val_metrics else 0.0\nlog("oof.csv rows=%d (strided from %d)" % (len(sampled), len(oof_rows)))\nlog("val dice=%.6f" % metric)\nlog("%s: %.6f" % (METRIC_NAME, metric))\n\n# ------------------------------------------------------------- submission\nsample_header = []\nsample_ids = []\nsample_vals = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    with open(SAMPLE_SUB, newline="", encoding="utf-8", errors="replace") as fh:\n        rows = list(csv.reader(fh))\n    if rows:\n        sample_header = rows[0]\n        for r in rows[1:]:\n            if r:\n                sample_ids.append(str(r[0]).strip())\n                sample_vals.append(r[1] if len(r) > 1 else "")\nif not sample_ids:\n    raise RuntimeError("compiled: sample submission has no id rows")\n\n# dense strategy needs per-id dims; fall back to empty when unknown\ndef _sub_value(sid):\n    if STRATEGY != "dense":\n        return EMPTY_MARK\n    row = None\n    sub = df[df["_id"] == sid]\n    if len(sub):\n        row = sub.iloc[0]\n    if row is None:\n        return EMPTY_MARK\n    h, w = _dims(row)\n    if h <= 0 or w <= 0:\n        return EMPTY_MARK\n    return _encode_rle(np.ones((h, w), dtype=bool))\n\ndef _sniff_newline(path):\n    try:\n        if path and os.path.isfile(path):\n            with open(path, "rb") as fh:\n                chunk = fh.read(8192)\n            if b"\\r\\n" in chunk:\n                return "\\r\\n"\n            if b"\\n" in chunk:\n                return "\\n"\n            if b"\\r" in chunk:\n                return "\\r"\n    except OSError:\n        pass\n    return "\\r\\n"\n\npred_cols = sample_header[1:] if len(sample_header) > 1 else [TARGET_COL]\nwith open("submission.csv", "w", newline="", encoding="utf-8") as fh:\n    w_csv = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n    w_csv.writerow(sample_header if sample_header else [id_col, pred_cols[0]])\n    for sid in sample_ids:\n        w_csv.writerow([sid, _sub_value(sid)])\nlog("submission.csv rows=%d cols=%s" % (len(sample_ids), pred_cols))\nlog("done wall=%.1fs" % (time.time() - T0))'

_IMAGE_DETECTION_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3.8 ProgramCompiler deterministic render (bbox detection baseline:\n# submission = organizer placeholder / empty box list; OOF = class-frequency\n# ranking per image so the internal map@k is defined and beatable).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\n\ndef log(msg):\n    print("[compiled] %s" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get("TRAIN_CSV") or "train.csv"\nSAMPLE_SUB = os.environ.get("SAMPLE_SUBMISSION") or ""\nTARGET_COL = (os.environ.get("TARGET_COLUMN") or "").strip()\nBBOX_COLUMNS = json.loads(os.environ.get("BBOX_COLUMNS") or "[]")\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get("val_seed", 42))\nMAX_CANDIDATES = int(PARAMS.get("max_candidates", 32) or 32)\nrandom.seed(SEED)\nnp.random.seed(SEED)\n\nimport pandas as pd\n\ndf = pd.read_csv(TRAIN_CSV, dtype=str)\nid_col = str(df.columns[0])\nif MAX_TRAIN_ROWS > 0 and len(df) > MAX_TRAIN_ROWS:\n    df = df.sample(n=MAX_TRAIN_ROWS, random_state=SEED)\ndf = df.dropna(subset=[id_col])\ndf["_id"] = df[id_col].astype(str).str.strip()\ndf = df[df["_id"] != ""]\n\n# class evidence column: class_id / class / label / category (first found)\nbox_set = set(BBOX_COLUMNS) if BBOX_COLUMNS else set()\nclass_col = ""\nfor name in ("class_id", "class", "label", "category", "category_id", "cls"):\n    if name in df.columns and name not in box_set and name != id_col:\n        class_col = name\n        break\nif not class_col:\n    for name in df.columns:\n        if str(name).lower() in ("class_id", "class", "label", "category",\n                                 "category_id", "cls") and name not in box_set:\n            class_col = name\n            break\n\ndef _row_tokens(row):\n    """Class tokens for one row: class column value, else JSON tokens\n    (kuzushiji utf8 / generic box objects)."""\n    toks = []\n    if class_col:\n        v = str(row.get(class_col, "")).strip()\n        if v and v.lower() not in ("nan", "none"):\n            toks.append(v)\n    else:\n        for name in (BBOX_COLUMNS or [TARGET_COL]):\n            if name not in df.columns:\n                continue\n            v = str(row.get(name, "")).strip()\n            if not v or v.lower() in ("nan", "none"):\n                continue\n            try:\n                obj = json.loads(v)\n            except (TypeError, ValueError):\n                obj = None\n            if isinstance(obj, list):\n                for item in obj:\n                    if isinstance(item, dict):\n                        tok = item.get("utf8") or item.get("label") or item.get("class") or item.get("category")\n                        if tok is not None:\n                            toks.append(str(tok))\n            elif isinstance(obj, dict):\n                tok = obj.get("utf8") or obj.get("label") or obj.get("class") or obj.get("category")\n                if tok is not None:\n                    toks.append(str(tok))\n    return toks\n\ndf["_tokens"] = df.apply(_row_tokens, axis=1)\ndf["_has_box"] = df["_tokens"].apply(lambda x: len(x) > 0)\n\n# candidates: most frequent class tokens (deterministic), capped\nfreq = {}\nfor toks in df["_tokens"]:\n    for t in set(toks):\n        freq[t] = freq.get(t, 0) + 1\nordered = sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))\ncandidates = [t for t, _ in ordered[:MAX_CANDIDATES]]\nif not candidates:\n    candidates = ["__obj__"]\n    freq["__obj__"] = 1\ntotal = float(sum(freq.values())) or 1.0\nscore = {t: freq.get(t, 0) / total for t in candidates}\n\n# ------------------------------------------------------------- holdout\nids = sorted(set(df["_id"]))\nrandom.shuffle(ids)\nn_val = max(1, int(round(len(ids) * 0.2)))\nval_ids = set(ids[:n_val])\nif not val_ids:\n    val_ids = set(ids)\nva = df[df["_id"].isin(val_ids)]\n\n# per-image token set\nimg_tokens = {}\nfor _, row in va.iterrows():\n    img_tokens.setdefault(str(row["_id"]), set()).update(row["_tokens"])\n\n# ------------------------------------------------------------- OOF\noof_rows = []\nn_pos = 0\nfor img, toks in sorted(img_tokens.items()):\n    for cand in candidates:\n        is_pos = 1 if cand in toks else 0\n        n_pos += is_pos\n        oof_rows.append((img, is_pos, "%.6f" % score.get(cand, 0.0)))\nif not oof_rows:\n    oof_rows.append(("__empty__", 1, "0.0"))\nwith open("oof.csv", "w", newline="", encoding="utf-8") as fh:\n    w_csv = csv.writer(fh)\n    w_csv.writerow(["query", "true", "pred"])\n    for img, t, p in oof_rows:\n        w_csv.writerow([img, t, p])\n# internal map@k estimate (mean over images with positives)\ndef _ap(rows):\n    rows = sorted(rows, key=lambda x: -x[2])\n    pos = sum(1 for _, t, _ in rows if t == 1)\n    if pos == 0:\n        return None\n    hits = 0\n    ap = 0.0\n    for rank, (_, t, _) in enumerate(rows[:5], start=1):\n        if t == 1:\n            hits += 1\n            ap += hits / rank\n    return ap / min(5, pos)\n\ngroups = {}\nfor img, t, p in oof_rows:\n    groups.setdefault(img, []).append((img, t, float(p)))\naps = [a for a in (_ap(g) for g in groups.values()) if a is not None]\nmetric = float(np.mean(aps)) if aps else 0.0\nlog("oof.csv rows=%d images=%d candidates=%d" % (len(oof_rows), len(groups), len(candidates)))\nlog("map_at_k: %.6f" % metric)\nlog("%s: %.6f" % (METRIC_NAME, metric))\n\n# ------------------------------------------------------------- submission\nsample_header = []\nsample_ids = []\nsample_vals = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    with open(SAMPLE_SUB, newline="", encoding="utf-8", errors="replace") as fh:\n        rows = list(csv.reader(fh))\n    if rows:\n        sample_header = rows[0]\n        for r in rows[1:]:\n            if r:\n                sample_ids.append(str(r[0]).strip())\n                sample_vals.append(r[1] if len(r) > 1 else "")\nif not sample_ids:\n    raise RuntimeError("compiled: sample submission has no id rows")\n\nnon_empty = [v for v in sample_vals if str(v).strip()]\nif non_empty and all(str(v).strip() == str(non_empty[0]).strip() for v in non_empty):\n    # organizer placeholder repeated for every row (vinbigdata "14 1 0 0 1 1",\n    # kuzushiji "[]", ...): reuse it.\n    def _sub_val(sid):\n        return str(non_empty[0]).strip()\n    _mode = "constant"\nelse:\n    def _has_unit_box(v):\n        parts = str(v).split()\n        return len(parts) >= 2 and parts[-5:] == ["1", "0", "0", "1", "1"]\n    if non_empty and all(_has_unit_box(v) for v in non_empty):\n        # siim-covid19 shape: "<label> 1 0 0 1 1" -> majority label + unit box\n        labels = []\n        for v in non_empty:\n            tok = str(v).split()[0]\n            labels.append(tok)\n        major = max(sorted(set(labels)), key=lambda x: labels.count(x))\n        def _sub_val(sid):\n            return "%s 1 0 0 1 1" % major\n        _mode = "majority_unit_box"\n    else:\n        # flat "label x y" triples or unknown: empty predictions are valid for\n        # kuzushiji (skipped) and keep the row-count contract everywhere.\n        def _sub_val(sid):\n            return ""\n        _mode = "empty"\n\npred_cols = sample_header[1:] if len(sample_header) > 1 else ["prediction"]\ndef _sniff_newline(path):\n    try:\n        if path and os.path.isfile(path):\n            with open(path, "rb") as fh:\n                chunk = fh.read(8192)\n            if b"\\r\\n" in chunk:\n                return "\\r\\n"\n            if b"\\n" in chunk:\n                return "\\n"\n            if b"\\r" in chunk:\n                return "\\r"\n    except OSError:\n        pass\n    return "\\r\\n"\n\nwith open("submission.csv", "w", newline="", encoding="utf-8") as fh:\n    w_csv = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n    w_csv.writerow(sample_header if sample_header else [id_col, pred_cols[0]])\n    for sid in sample_ids:\n        w_csv.writerow([sid, _sub_val(sid)])\nlog("submission.csv rows=%d mode=%s cols=%s" % (len(sample_ids), _mode, pred_cols))\nlog("done wall=%.1fs" % (time.time() - T0))'

_AUDIO_BASELINE_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.3.8 ProgramCompiler deterministic render (audio baseline: majority\n# class / per-class frequency; works for single-label and multi-label\n# audio tasks without reading any audio bytes).\nimport os, sys, json, csv, math, random, time\nimport numpy as np\n\ndef log(msg):\n    print("[compiled] %s" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get("TRAIN_CSV") or "train.csv"\nSAMPLE_SUB = os.environ.get("SAMPLE_SUBMISSION") or ""\nTARGET_COL = (os.environ.get("TARGET_COLUMN") or "").strip()\nMETRIC_NAME = \'@@METRIC_NAME@@\'\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSEED = int(PARAMS.get("val_seed", 42))\nrandom.seed(SEED)\nnp.random.seed(SEED)\n\nimport pandas as pd\n\ndf = pd.read_csv(TRAIN_CSV, dtype=str)\nid_col = str(df.columns[0])\nif MAX_TRAIN_ROWS > 0 and len(df) > MAX_TRAIN_ROWS:\n    df = df.sample(n=MAX_TRAIN_ROWS, random_state=SEED)\ndf = df.dropna(subset=[id_col])\ndf["_id"] = df[id_col].astype(str).str.strip()\ndf = df[df["_id"] != ""]\n\nnon_id = [str(c) for c in df.columns if str(c) != id_col]\n\n# multi-label: >= 3 non-id columns whose values are all 0/1 (freesound shape)\ndef _is_binary(col):\n    vals = [str(v).strip() for v in df[col].dropna() if str(v).strip()]\n    if not vals:\n        return False\n    return all(v in ("0", "1") for v in vals)\n\nmulti_cols = [c for c in non_id if _is_binary(c)] if len(non_id) >= 3 else []\nMULTI = len(multi_cols) >= 3\nif MULTI:\n    target_cols = multi_cols\nelse:\n    target_cols = []\n    if not TARGET_COL or TARGET_COL not in df.columns:\n        TARGET_COL = non_id[-1] if non_id else str(df.columns[-1])\n\n# ------------------------------------------------------------- holdout\nids = sorted(set(df["_id"]))\nrandom.shuffle(ids)\nn_val = max(1, int(round(len(ids) * 0.2)))\nval_ids = set(ids[:n_val])\nif not val_ids:\n    val_ids = set(ids)\ntr = df[~df["_id"].isin(val_ids)]\nva = df[df["_id"].isin(val_ids)]\nif len(tr) == 0:\n    tr = va\n    va = va.iloc[0:0]\n\n# ------------------------------------------------------------- OOF\noof_rows = []\nif MULTI:\n    freqs = {}\n    for c in target_cols:\n        vals = pd.to_numeric(tr[c], errors="coerce").fillna(0.0)\n        freqs[c] = float(vals.mean()) if len(vals) else 0.0\n    for _, row in va.iterrows():\n        rec = {"query": str(row["_id"]), "true": "0", "pred": "0"}\n        for c in target_cols:\n            tv = 1 if str(row.get(c, "")).strip() in ("1", "true", "True") else 0\n            rec["true_" + c] = tv\n            rec["pred_" + c] = "%.6f" % freqs.get(c, 0.0)\n        oof_rows.append(rec)\n    with open("oof.csv", "w", newline="", encoding="utf-8") as fh:\n        cols = ["query", "true", "pred"] + \\\n               ["true_" + c for c in target_cols] + ["pred_" + c for c in target_cols]\n        w = csv.DictWriter(fh, fieldnames=cols)\n        w.writeheader()\n        for r in oof_rows:\n            w.writerow(r)\n    # internal LRAP estimate\n    total = 0.0\n    weight = 0.0\n    for r in oof_rows:\n        pos = [c for c in target_cols if r["true_" + c] == 1]\n        if not pos:\n            continue\n        lrap = 0.0\n        for c in pos:\n            cur = float(r["pred_" + c])\n            pos_ge = sum(1 for d in pos if float(r["pred_" + d]) >= cur)\n            ge = sum(1 for d in target_cols if float(r["pred_" + d]) >= cur)\n            if ge:\n                lrap += pos_ge / ge\n        lrap /= len(pos)\n        total += lrap * len(pos)\n        weight += len(pos)\n    metric = total / weight if weight else 0.0\n    log("oof.csv rows=%d multi-label cols=%d" % (len(oof_rows), len(target_cols)))\n    log("label_ranking_ap: %.6f" % metric)\n    log("%s: %.6f" % (METRIC_NAME, metric))\nelse:\n    y = tr[TARGET_COL].astype(str).str.strip()\n    counts = y.value_counts()\n    if len(counts):\n        majority = str(counts.index[0])\n        major_frac = float(counts.iloc[0]) / max(1, len(y))\n    else:\n        majority = ""\n        major_frac = 0.0\n    if METRIC_NAME in ("mean_auc_multilabel", "label_ranking_ap", "auc",\n                       "binary_logloss", "weighted_logloss", "logloss"):\n        # probability-family: per-class probability columns (single target)\n        classes = sorted(set(y))\n        prob = {}\n        for c in classes:\n            prob[c] = float((y == c).mean())\n        rows_out = []\n        for _, row in va.iterrows():\n            tv = str(row.get(TARGET_COL, "")).strip()\n            rec = {"query": str(row["_id"]), "true": tv, "pred": majority}\n            for c in classes:\n                rec["true_" + c] = 1 if tv == c else 0\n                rec["pred_" + c] = "%.6f" % prob.get(c, 0.0)\n            rows_out.append(rec)\n        with open("oof.csv", "w", newline="", encoding="utf-8") as fh:\n            cols = ["query", "true", "pred"] + \\\n                   ["true_" + c for c in classes] + ["pred_" + c for c in classes]\n            w = csv.DictWriter(fh, fieldnames=cols)\n            w.writeheader()\n            for r in rows_out:\n                w.writerow(r)\n        log("oof.csv rows=%d classes=%d" % (len(rows_out), len(classes)))\n        log("mean_auc_multilabel: %.6f" % 0.5)\n        log("%s: %.6f" % (METRIC_NAME, 0.5))\n    else:\n        rows_out = []\n        for _, row in va.iterrows():\n            rows_out.append((str(row.get(TARGET_COL, "")).strip(), majority))\n        with open("oof.csv", "w", newline="", encoding="utf-8") as fh:\n            w = csv.writer(fh)\n            w.writerow(["true", "pred"])\n            for t, p in rows_out:\n                w.writerow([t, p])\n        log("oof.csv rows=%d majority=%r frac=%.4f" % (len(rows_out), majority, major_frac))\n        log("accuracy: %.6f" % major_frac)\n        log("%s: %.6f" % (METRIC_NAME, major_frac))\n\n# ------------------------------------------------------------- submission\nsample_header = []\nsample_ids = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    with open(SAMPLE_SUB, newline="", encoding="utf-8", errors="replace") as fh:\n        rows = list(csv.reader(fh))\n    if rows:\n        sample_header = rows[0]\n        sample_ids = [str(r[0]).strip() for r in rows[1:] if r]\nif not sample_ids:\n    raise RuntimeError("compiled: sample submission has no id rows")\n\npred_cols = sample_header[1:] if len(sample_header) > 1 else [TARGET_COL]\ndef _sniff_newline(path):\n    try:\n        if path and os.path.isfile(path):\n            with open(path, "rb") as fh:\n                chunk = fh.read(8192)\n            if b"\\r\\n" in chunk:\n                return "\\r\\n"\n            if b"\\n" in chunk:\n                return "\\n"\n            if b"\\r" in chunk:\n                return "\\r"\n    except OSError:\n        pass\n    return "\\r\\n"\n\nif MULTI:\n    # multi-label: predict the per-class frequency (deterministic; all-zero\n    # when the majority is 0, which is the freesound majority case).\n    with open("submission.csv", "w", newline="", encoding="utf-8") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col] + target_cols)\n        for sid in sample_ids:\n            w.writerow([sid] + ["%.6f" % freqs.get(c, 0.0) for c in target_cols])\n    log("submission.csv rows=%d multi-label cols=%d" % (len(sample_ids), len(target_cols)))\nelse:\n    with open("submission.csv", "w", newline="", encoding="utf-8") as fh:\n        w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n        w.writerow(sample_header if sample_header else [id_col, TARGET_COL])\n        for sid in sample_ids:\n            w.writerow([sid, majority])\n    log("submission.csv rows=%d cols=%s" % (len(sample_ids), pred_cols))\nlog("done wall=%.1fs" % (time.time() - T0))'

_FRAGMENT_LINEAR = 'def make_estimator(seed):\n    return _BUILD_SINGLE("tabular.linear.logistic.v1", seed)\n'
_FRAGMENT_HISTGB = 'def make_estimator(seed):\n    return _BUILD_SINGLE("tabular.gbdt.histgb.v1", seed)\n'
_FRAGMENT_MLP = 'def make_estimator(seed):\n    return _BUILD_SINGLE("tabular.neural.mlp.v1", seed)\n'
_FRAGMENT_TEXT_TFIDF = 'def make_estimator(seed):\n    return _BUILD_SINGLE("text.embedding.tfidf.v1", seed)\n'
_FRAGMENT_TEXT_MLP = 'def _densify(X):\n    return X.toarray() if hasattr(X, "toarray") else X\n\nclass _DenseAdapter:\n    """MLP cannot ingest scipy sparse: adapt after TF-IDF."""\n    def __init__(self, est):\n        self.est = est\n\n    def fit(self, X, y):\n        self.est.fit(_densify(X), y)\n        return self\n\n    def predict_proba(self, X):\n        return self.est.predict_proba(_densify(X))\n\n    def predict(self, X):\n        return self.est.predict(_densify(X))\n\n    @property\n    def classes_(self):\n        return self.est.classes_\n\ndef make_estimator(seed):\n    return _DenseAdapter(_BUILD_SINGLE("text.neural.mlp.v1", seed))\n'
_FRAGMENT_TS_LAG = 'def make_estimator(seed):\n    return _BUILD_SINGLE("timeseries.lag_histgb.v1", seed)\n'

def _ensemble_fragment(method_ids: List[str], weights: List[float]) -> str:
    return _FRAGMENT_ENSEMBLE_TMPL.replace(
        "@@ENSEMBLE_METHODS_JSON@@", json.dumps([str(m) for m in (method_ids or [])])
    ).replace(
        "@@ENSEMBLE_WEIGHTS_JSON@@", json.dumps([float(w) for w in (weights or [])])
    )

_FRAGMENT_ENSEMBLE_TMPL = 'ENSEMBLE_METHODS = @@ENSEMBLE_METHODS_JSON@@\nENSEMBLE_WEIGHTS = @@ENSEMBLE_WEIGHTS_JSON@@\n\nclass _Ensemble:\n    def __init__(self, seed):\n        self.seed = int(seed)\n        self.models = []\n        self.weights = []\n        self.classes_ = None\n\n    def fit(self, X, y):\n        mids = [m for m in ENSEMBLE_METHODS if m] or ["tabular.linear.logistic.v1"]\n        for mid in mids:\n            m = _BUILD_SINGLE(mid, self.seed)\n            if MULTI_TARGET:\n                from sklearn.multioutput import MultiOutputRegressor\n                m = MultiOutputRegressor(m, n_jobs=1)\n            m.fit(X, y)\n            self.models.append(m)\n        w = ENSEMBLE_WEIGHTS\n        if not w or len(w) != len(self.models):\n            w = [1.0 / len(self.models)] * len(self.models)\n        self.weights = [float(x) for x in w]\n        self.classes_ = getattr(self.models[0], "classes_", None)\n        return self\n\n    def predict_proba(self, X):\n        P = None\n        for m, w in zip(self.models, self.weights):\n            p = m.predict_proba(X)\n            P = (w * p) if P is None else (P + w * p)\n        return P\n\n    def predict(self, X):\n        if is_classification:\n            P = self.predict_proba(X)\n            return np.array([str(self.classes_[int(np.argmax(r))]) for r in P])\n        return np.mean([m.predict(X) for m in self.models], axis=0)\n\ndef make_estimator(seed):\n    return _Ensemble(seed)\n'

# ------------------------------------------------- v2.5.0 template registry
# Declarative renderer routing: a renderer name maps to ONE template/fragment
# definition. There is NO if/elif chain anywhere in the compiler that picks a
# template by name -- adding a method means adding one registry entry, and
# method selection stays entirely in the capability/metadata layer.


@dataclass
class _TemplateDef:
    """One declarative renderer entry.

    tag:       stable schema tag included in the template hash
    template:  full self-contained script (image/audio/... renderers)
    fragment:  estimator-builder fragment injected into _TABULAR_HARNESS
    fragment_fn: optional (params: dict) -> fragment (dynamic fragments,
               e.g. ensemble member lists baked at seal time)
    """
    tag: str
    template: str = ""
    fragment: str = ""
    fragment_fn: Optional[Callable[[Dict[str, Any]], str]] = None
    time_policy: str = "derive"   # "lag" (time-ordered lag/rolling, timeseries
                                  # renderers) | "derive" (calendar/elapsed
                                  # datetime features, default for tabular)


def _ensemble_fragment_from_params(params: Dict[str, Any]) -> str:
    return _ensemble_fragment(params.get("model_ids") or [],
                              params.get("weights") or [])


_STRING_LOOKUP_TEMPLATE = '# -*- coding: utf-8 -*-\n# v2.5.6 ProgramCompiler deterministic render (string-target lookup).\n# Template hash is frozen at seal time; every child with the same\n# invocation renders bit-identical code. Generic: a high-cardinality\n# string target is predicted by a most-frequent lookup over a source\n# column whose values often equal the target, with a copy-source\n# fallback. No sklearn model is trained over millions of distinct\n# labels; this renderer finishes in seconds on large string targets.\nimport os, sys, json, csv, math, random, time\nimport numpy as np\nimport pandas as pd\n\ndef log(msg):\n    print(\"[compiled] %s\" % msg, flush=True)\n\nT0 = time.time()\nTRAIN_CSV = os.environ.get(\"TRAIN_CSV\") or \"train.csv\"\nTEST_CSV = os.environ.get(\"TEST_CSV\") or \"test.csv\"\nSAMPLE_SUB = os.environ.get(\"SAMPLE_SUBMISSION\") or \"\"\nTARGET_COL = (os.environ.get(\"TARGET_COLUMN\") or \"\").strip()\nPARAMS = json.loads(\'@@PARAMS_JSON@@\')\nMAX_TRAIN_ROWS = int(\'@@MAX_TRAIN_ROWS@@\' or \'0\')\nSOURCE_COL = \'@@STRING_SOURCE_COLUMN@@\'\nSEED = int(PARAMS.get(\"val_seed\", 42))\nrandom.seed(SEED)\nnp.random.seed(SEED)\n\n_nrows = int(MAX_TRAIN_ROWS) if MAX_TRAIN_ROWS > 0 else None\ndf_train = pd.read_csv(TRAIN_CSV, nrows=_nrows)\ndf_test = pd.read_csv(TEST_CSV)\n\n# ------------------------------------------------------------------ id column\nsample_header = []\nif SAMPLE_SUB and os.path.isfile(SAMPLE_SUB):\n    try:\n        sample_header = [str(c) for c in pd.read_csv(SAMPLE_SUB, nrows=0).columns]\n    except Exception:\n        sample_header = []\nSAMPLE_PASSTHROUGH = [str(c) for c in sample_header if str(c) in df_test.columns]\nSAMPLE_OUTPUT = [str(c) for c in sample_header if str(c) not in df_test.columns]\nid_col = SAMPLE_PASSTHROUGH[0] if SAMPLE_PASSTHROUGH else None\nif id_col is None or id_col not in df_test.columns:\n    id_col = next((c for c in (\"id\", \"Id\", \"ID\", \"index\") if c in df_test.columns), None)\nif id_col is None or id_col not in df_test.columns:\n    id_col = str(df_test.columns[0])\n\nif not TARGET_COL or TARGET_COL not in df_train.columns:\n    cands = [str(c) for c in df_train.columns if str(c) != id_col]\n    TARGET_COL = cands[-1] if cands else str(df_train.columns[-1])\n\n# v2.5.6 compound-id synthesis: when the sample id column is absent from\n# test.csv but equals a \"_\"-join of test columns (e.g. \"sentence_id\" +\n# \"token_id\" -> \"0_0\"), synthesize the join key so every sample row maps\n# to exactly one test row.\nSYN_COLS = []\n_SYN_ID_COL = \"\"\nif not SAMPLE_PASSTHROUGH and sample_header:\n    _sid = str(sample_header[0])\n    _test_cols = [str(c) for c in df_test.columns]\n    _sample_ids = None\n    try:\n        _sdf = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n        if _sid in _sdf.columns:\n            _sample_ids = [str(v).strip() for v in _sdf[_sid].values]\n    except Exception:\n        _sample_ids = None\n    if _sample_ids and _test_cols:\n        _check_n = min(200, len(_sample_ids))\n\n        def _matches(cols):\n            if not cols:\n                return False\n            for k in range(_check_n):\n                parts = [str(df_test[c].astype(str).iloc[k]).strip()\n                         for c in cols]\n                if \"_\".join(parts) != _sample_ids[k]:\n                    return False\n            return True\n\n        _found = []\n        for c in _test_cols:\n            if _matches([c]):\n                _found = [c]\n                break\n        if not _found and len(_test_cols) <= 12:\n            for i in range(len(_test_cols)):\n                for j in range(i + 1, len(_test_cols)):\n                    if _matches([_test_cols[i], _test_cols[j]]):\n                        _found = [_test_cols[i], _test_cols[j]]\n                        break\n                if _found:\n                    break\n        if _found:\n            SYN_COLS = _found\n            _SYN_ID_COL = _sid\n            SAMPLE_PASSTHROUGH = list(_found)\n            id_col = _found[0]\n            log(\"compound id: %s = %s\" % (_sid, \"+\".join(_found)))\n            SAMPLE_OUTPUT = [str(c) for c in SAMPLE_OUTPUT\n                            if str(c) != _SYN_ID_COL]\n\n# ------------------------------------------------------------ source column\nif (not SOURCE_COL or SOURCE_COL not in df_train.columns\n        or SOURCE_COL not in df_test.columns):\n    _best, _best_ov = \"\", -1.0\n    _cands = [str(c) for c in df_train.columns\n              if str(c) != TARGET_COL and str(c) != id_col\n              and str(c) in df_test.columns]\n    for _c in _cands[:50]:\n        _ov = float((df_train[_c].astype(str).str.strip()\n                     == df_train[TARGET_COL].astype(str).str.strip()).mean())\n        if _ov > _best_ov:\n            _best, _best_ov = _c, _ov\n    if _best_ov >= 0.4:\n        SOURCE_COL = _best\n        log(\"source column fallback: %s (overlap %.3f)\" % (_best, _best_ov))\n\n# ------------------------------------------------------------------- lookup\ntr_src = (df_train[SOURCE_COL].astype(str).str.strip().values\n          if SOURCE_COL else None)\ntr_tgt = df_train[TARGET_COL].astype(str).str.strip().values\nn = len(df_train)\nMIN_COUNT = max(1, int(PARAMS.get(\"min_count\", 1) or 1))\n\nfrom collections import Counter, defaultdict\n\ndef _build_lookup(idx):\n    cts = defaultdict(Counter)\n    if tr_src is not None:\n        for s, t in zip(tr_src[idx], tr_tgt[idx]):\n            cts[s][t] += 1\n    return cts\n\ndef _majority_target():\n    c = Counter(tr_tgt)\n    return c.most_common(1)[0][0] if c else \"\"\n\n_MAJORITY = _majority_target()\n\ndef _predict_one(k, cts):\n    if tr_src is None:\n        return _MAJORITY\n    key = str(k).strip()\n    c = cts.get(key)\n    if c:\n        best_t, best_key = None, (-1, -1)\n        for t, cnt in c.items():\n            _key = (cnt, 1 if t == key else 0)\n            if _key > best_key:\n                best_t, best_key = t, _key\n        if best_key[0] >= MIN_COUNT:\n            return best_t\n    return key\n\n# ---------------------------------------------------------------------- OOF\nrng = np.random.RandomState(SEED)\nperm = rng.permutation(n)\nn_oof = max(1, int(n * 0.2))\nif n_oof >= n:\n    n_oof = max(1, n // 2)\nfit_idx = np.sort(perm[n_oof:])\noof_idx = np.sort(perm[:n_oof])\ncts_fit = _build_lookup(fit_idx)\noof_rows = []\nfor j in oof_idx:\n    oof_rows.append((tr_tgt[j], _predict_one(\n        tr_src[j] if tr_src is not None else \"\", cts_fit)))\n_acc = sum(1 for t, p in oof_rows if t == p) / float(len(oof_rows))\nwith open(\"oof.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n    w = csv.writer(fh)\n    w.writerow([\"true\", \"pred\"])\n    for t, p in oof_rows:\n        w.writerow([t, p])\nlog(\"oof.csv rows=%d accuracy: %.6f\" % (len(oof_rows), _acc))\n\n# ------------------------------------------------------------ submission\ndef _sniff_newline(path):\n    try:\n        if path and os.path.isfile(path):\n            with open(path, \"rb\") as fh:\n                chunk = fh.read(8192)\n            if b\"\\r\\n\" in chunk:\n                return \"\\r\\n\"\n            if b\"\\n\" in chunk:\n                return \"\\n\"\n            if b\"\\r\" in chunk:\n                return \"\\r\"\n    except OSError:\n        pass\n    return \"\\r\\n\"\n\ncts_all = _build_lookup(np.arange(n))\ntest_src = (df_test[SOURCE_COL].astype(str).str.strip().values\n            if SOURCE_COL else np.array([\"\"] * len(df_test)))\ntest_preds = [_predict_one(v, cts_all) for v in test_src]\n\npred_cols = SAMPLE_OUTPUT if SAMPLE_OUTPUT else [TARGET_COL]\npassthrough = SAMPLE_PASSTHROUGH if SAMPLE_PASSTHROUGH else [id_col]\ntest_key_to_idx = {}\nif SYN_COLS:\n    _kvals = df_test[SYN_COLS[0]].astype(str).str.strip()\n    for _c in SYN_COLS[1:]:\n        _kvals = _kvals + \"_\" + df_test[_c].astype(str).str.strip()\n    for _ri, _k in enumerate(_kvals.values):\n        test_key_to_idx.setdefault(str(_k), _ri)\nelse:\n    for _ri in range(len(df_test)):\n        _rk = tuple(str(df_test[c].astype(str).iloc[_ri]) for c in passthrough)\n        test_key_to_idx.setdefault(_rk, _ri)\nif sample_header:\n    rows = pd.read_csv(SAMPLE_SUB, dtype=str).fillna(\"\")\n    records = rows.to_dict(\"records\")\nelse:\n    records = [dict(zip(passthrough, [str(v) for v in r])) for r in\n               df_test[id_col].astype(str).values]\nwith open(\"submission.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as fh:\n    w = csv.writer(fh, lineterminator=_sniff_newline(SAMPLE_SUB))\n    w.writerow(sample_header if sample_header else passthrough + pred_cols)\n    for rec in records:\n        if SYN_COLS:\n            _rk = str(rec.get(_SYN_ID_COL, \"\")).strip()\n        else:\n            _rk = tuple(str(rec.get(c, \"\")) for c in passthrough)\n        i = test_key_to_idx.get(_rk, 0)\n        pred = test_preds[i] if i < len(test_preds) else test_preds[0]\n        pred_str = str(pred)\n        row = []\n        for cname in (sample_header if sample_header\n                      else passthrough + pred_cols):\n            if cname in pred_cols:\n                row.append(pred_str)\n            else:\n                row.append(str(rec.get(cname, \"\")))\n        w.writerow(row)\nlog(\"submission.csv rows=%d cols=%s\" % (len(records), pred_cols))\nlog(\"done wall=%.1fs\" % (time.time() - T0))\n'


