# ------------------------------------------------------------ compile errors
class CompileError(RuntimeError):
    """Invocation/render failure: the proposal cannot be compiled."""


def _to_float(v) -> Optional[float]:
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _check_param(ps: dict, v: Any) -> Tuple[bool, str]:
    t = ps.get("type", "")
    if t == "float":
        f = _to_float(v)
        if f is None:
            return False, "param value %r is not float" % (v,)
        if "min" in ps and f < float(ps["min"]) - 1e-9:
            return False, "param %r < min %s" % (v, ps["min"])
        if "max" in ps and f > float(ps["max"]) + 1e-9:
            return False, "param %r > max %s" % (v, ps["max"])
        return True, ""
    if t == "int":
        try:
            iv = int(v)
        except (TypeError, ValueError):
            return False, "param value %r is not int" % (v,)
        if str(iv) != str(v).strip():
            return False, "param value %r is not an int" % (v,)
        if "min" in ps and iv < int(ps["min"]):
            return False, "param %d < min %s" % (iv, ps["min"])
        if "max" in ps and iv > int(ps["max"]):
            return False, "param %d > max %s" % (iv, ps["max"])
        return True, ""
    if t == "bool":
        if v not in (True, False, 0, 1, "true", "false", "True", "False"):
            return False, "param value %r is not bool" % (v,)
        return True, ""
    if t == "str":
        s = str(v)
        if ps.get("choices") and s not in [str(c) for c in ps["choices"]]:
            return False, "value %r not in choices" % (s,)
        return True, ""
    if t == "list":
        if not isinstance(v, (list, tuple)):
            return False, "param value %r is not a list" % (v,)
        if "max_len" in ps and len(v) > int(ps["max_len"]):
            return False, "list longer than max_len %s" % ps["max_len"]
        return True, ""
    return True, ""


_RESOURCE_KEYS = ("max_train_rows", "folds", "epochs", "image_size",
                  "batch_size")
