class ProgramCompiler:
    """Validates MethodInvocationV1 and renders deterministic code."""

    def __init__(self, registry: CapabilityRegistry):
        self.registry = registry

    # ------------------------------------------------------------ normalize
    def normalize(self, invocation: Any) -> MethodInvocationV1:
        inv = (MethodInvocationV1.from_dict(invocation)
               if isinstance(invocation, dict) else invocation)
        spec = self.registry.get(inv.method_id or "")
        params: Dict[str, Any] = {}
        if spec is not None:
            for k, ps in (spec.parameter_schema or {}).items():
                if "default" in ps:
                    params[k] = ps["default"]
        params.update(dict(inv.params or {}))
        rr = {}
        for k in _RESOURCE_KEYS:
            if k in (inv.resource_request or {}):
                rr[k] = inv.resource_request[k]
        if "patch_round" in (inv.resource_request or {}):
            rr["patch_round"] = inv.resource_request["patch_round"]
        # v2.5.4: platform row cap (runnability default, declared per
        # capability in the registry). The compiled templates subsample to
        # MAX_TRAIN_ROWS so large datasets (e.g. 200k-row tabular tasks)
        # finish inside the planned trial budget; explicit HERA requests
        # pass through unchanged (the closed loop clamps them to the
        # derived resource profile cap).
        if "max_train_rows" not in rr and spec is not None:
            _dflt_rows = int(getattr(spec, "default_max_train_rows", 0) or 0)
            if _dflt_rows > 0:
                rr["max_train_rows"] = _dflt_rows
        # Platform defaults are about RUNNABILITY, not research choice:
        # each capability declares its safe default preprocessing and
        # validation in the registry (method-level prior); HERA's explicit
        # choices always win, except for "fixed" validation schemes that
        # a template implements as its only honest split.
        pre = [_PREPROC_ALIASES.get(str(p).strip().lower(), p)
               for p in (inv.preprocessing or [])]
        if not pre and spec is not None:
            pre = list(spec.default_preprocessing or [])
        _def_val = "stratified_kfold"
        if spec is not None and spec.default_validation:
            _def_val = spec.default_validation
        _val = _VALIDATION_ALIASES.get(
            str(inv.validation or "").strip().lower(), inv.validation)
        _val = _val or _def_val
        if spec is not None and spec.validation_policy == "fixed" and \
                _val != _def_val:
            # fixed validation: the template implements exactly one honest
            # split (time_holdout for lag models, single_holdout for
            # pixel/mask/detection/audio baselines), so any other request
            # is normalized to the declared scheme instead of silently
            # producing a dishonest split.
            _val = _def_val
        return MethodInvocationV1(
            method_id=inv.method_id,
            params=params,
            preprocessing=pre,
            validation=_val,
            hypothesis=inv.hypothesis,
            resource_request=rr,
        )

    # ------------------------------------------------------------ validation
    def validate(self, invocation: Any, profile=None, manifest=None
                 ) -> Tuple[bool, str]:
        inv = self.normalize(invocation)
        if not inv.method_id:
            return False, "empty method_id"
        spec = self.registry.get(inv.method_id)
        if spec is None:
            return False, "unknown method_id %s" % inv.method_id
        if spec.broken:
            return False, "capability %s marked broken" % inv.method_id
        modality, task_type, metric_name = _contract(profile, manifest)
        if spec.supported_modalities and modality and \
                modality not in spec.supported_modalities:
            return False, ("modality %s not supported by %s"
                           % (modality, inv.method_id))
        if spec.supported_tasks and task_type and \
                task_type not in spec.supported_tasks:
            return False, ("task_type %s not supported by %s"
                           % (task_type, inv.method_id))
        if metric_name and spec.metric_outputs and \
                metric_name not in spec.metric_outputs:
            return False, ("metric %s not produced by %s"
                           % (metric_name, inv.method_id))
        schema = spec.parameter_schema or {}
        for k, v in (inv.params or {}).items():
            if k not in schema:
                return False, "unknown param %s for %s" % (k, inv.method_id)
            ok, reason = _check_param(schema[k], v)
            if not ok:
                return False, "param %s: %s" % (k, reason)
        opts = spec.preprocessing_options or []
        for p in (inv.preprocessing or []):
            if p not in opts:
                return False, "preprocessing %s not offered by %s" % (p, inv.method_id)
        if inv.validation and inv.validation not in (spec.validation_schemes or []):
            return False, "validation %s not offered by %s" % (inv.validation, inv.method_id)
        for k in (inv.resource_request or {}):
            if k not in _RESOURCE_KEYS + ("patch_round",):
                return False, "unknown resource_request key %s" % k
        return True, ""

    # ---------------------------------------------------------------- render
    def render(self, invocation: Any, profile=None, manifest=None
               ) -> Tuple[str, str]:
        """Deterministically render code. Returns (code, template_hash)."""
        ok, reason = self.validate(invocation, profile, manifest)
        if not ok:
            raise CompileError(reason)
        inv = self.normalize(invocation)
        spec = self.registry.get(inv.method_id)
        if spec is None:
            raise CompileError("unknown method_id %s" % inv.method_id)
        if spec.ephemeral:
            return self.render_ephemeral(inv, spec, profile, manifest)
        tdef = _TEMPLATE_REGISTRY.get(spec.renderer)
        if tdef is None:
            raise CompileError("no renderer for %s" % spec.renderer)
        _, _, metric_name = _contract(profile, manifest)
        kind = (spec.metric_outputs or {}).get(metric_name or "", "class")
        max_rows = int((inv.resource_request or {}).get("max_train_rows") or 0)
        token_params = json.dumps(inv.params, sort_keys=True)
        token_pre = json.dumps(list(inv.preprocessing or []))
        text_cols = []
        if profile is not None:
            text_cols = [str(c) for c in (getattr(profile, "text_columns", None) or [])]
        if not text_cols and manifest is not None:
            text_cols = [str(c) for c in (manifest.get("text_columns") or [])]
        datetime_cols = []
        if profile is not None:
            datetime_cols = [str(c) for c in (
                getattr(profile, "datetime_columns", None) or [])]
        if not datetime_cols and manifest is not None:
            datetime_cols = [str(c) for c in (
                manifest.get("datetime_columns") or [])]
        time_col = ""
        if profile is not None:
            time_col = str(getattr(profile, "time_column", "") or "")
        if not time_col and manifest is not None:
            time_col = str(manifest.get("time_column") or "")
        modality = ""
        if profile is not None:
            modality = str(getattr(profile, "modality", "") or "")
        if not modality and manifest is not None:
            modality = str(manifest.get("modality") or "")
        # v2.5.1: the lag renderer declares time_policy="lag"; every other
        # renderer keeps LAG_COLUMN empty and derives datetime features
        # instead (declarative registry metadata, never a name branch).
        lag_column = time_col if tdef.time_policy == "lag" else ""
        string_source = ""
        if profile is not None:
            string_source = str(getattr(profile,
                                      "string_source_column", "") or "")
        if not string_source and manifest is not None:
            string_source = str(manifest.get("string_source_column") or "")
        common = {
            "@@PARAMS_JSON@@": token_params,
            "@@PREPROCESSING_JSON@@": token_pre,
            "@@VALIDATION@@": str(inv.validation or "stratified_kfold"),
            "@@METRIC_NAME@@": metric_name or "accuracy",
            "@@METRIC_KIND@@": kind,
            "@@MAX_TRAIN_ROWS@@": str(max(0, int(max_rows))),
            "@@STRING_SOURCE_COLUMN@@": string_source,
            "@@TEXT_COLUMNS_JSON@@": json.dumps(text_cols),
            "@@DATETIME_COLUMNS_JSON@@": json.dumps(datetime_cols),
            "@@LAG_COLUMN@@": lag_column,
            "@@MODALITY@@": modality,
        }
        if tdef.template:
            code = tdef.template
            for k, v in common.items():
                code = code.replace(k, v)
            th = "sha256:" + hashlib.sha256(
                (TEMPLATE_SCHEMA + "|" + tdef.tag + "|" + tdef.template)
                .encode("utf-8")).hexdigest()
            return code, th
        if tdef.fragment_fn is not None:
            fragment = tdef.fragment_fn(inv.params or {})
        else:
            fragment = tdef.fragment
        code = _TABULAR_HARNESS
        for k, v in common.items():
            code = code.replace(k, v)
        code = code.replace("@@FRAGMENT@@", fragment)
        th = "sha256:" + hashlib.sha256(
            (TEMPLATE_SCHEMA + "|" + tdef.tag + "|" + spec.renderer + "|"
             + _TABULAR_HARNESS + "|" + fragment).encode("utf-8")).hexdigest()
        return code, th

    # ------------------------------------------------------------- ephemeral
    def render_ephemeral(self, invocation: Any, spec: MethodSpec,
                         profile=None, manifest=None) -> Tuple[str, str]:
        """Phase C: wrap an LLM-synthesized estimator builder in the harness.

        The LLM writes ONLY a `def build_model(params, seed): ...` body
        (source_code). The compiler renders the same deterministic harness
        with that body injected; every later child changes parameters only.
        """
        inv = self.normalize(invocation)
        body = (spec.source_code or "").strip()
        if not body:
            raise CompileError("ephemeral capability has empty source_code")
        if "def build_model" not in body:
            raise CompileError("ephemeral source_code must define build_model")
        _, _, metric_name = _contract(profile, manifest)
        kind = (spec.metric_outputs or {}).get(metric_name or "", "class")
        max_rows = int((inv.resource_request or {}).get("max_train_rows") or 0)
        fragment = body + "\n\ndef make_estimator(seed):\n    return build_model(PARAMS, seed)\n"
        code = _TABULAR_HARNESS
        code = code.replace("@@PARAMS_JSON@@",
                            json.dumps(inv.params, sort_keys=True))
        code = code.replace("@@PREPROCESSING_JSON@@",
                            json.dumps(list(inv.preprocessing or [])))
        code = code.replace("@@VALIDATION@@",
                            str(inv.validation or "stratified_kfold"))
        code = code.replace("@@METRIC_NAME@@", metric_name or "accuracy")
        code = code.replace("@@METRIC_KIND@@", kind)
        code = code.replace("@@MAX_TRAIN_ROWS@@", str(max(0, int(max_rows))))
        code = code.replace("@@TEXT_COLUMNS_JSON@@", "[]")
        code = code.replace("@@DATETIME_COLUMNS_JSON@@", "[]")
        code = code.replace("@@LAG_COLUMN@@", "")
        code = code.replace("@@MODALITY@@", "")
        code = code.replace("@@FRAGMENT@@", fragment)
        th = "sha256:" + hashlib.sha256(
            (TEMPLATE_SCHEMA + "|ephemeral|" + (spec.template_hash or "")
             + "|" + body).encode("utf-8")).hexdigest()
        return code, th

    # ------------------------------------------------------- repair patching
    def patch_params(self, invocation: Any, error_tail: str = ""
                     ) -> Tuple[Optional[MethodInvocationV1], str]:
        """Crash-driven parameter micro-adjustment (repair only).

        Picks the next deterministic candidate in priority order and halves
        it (floor at schema min). Returns None when no candidate remains.
        """
        inv = self.normalize(invocation)
        spec = self.registry.get(inv.method_id or "")
        if spec is None:
            return None, "unknown method_id"
        schema = spec.parameter_schema or {}
        round_n = int((inv.resource_request or {}).get("patch_round") or 0)
        idx = 0
        for name in _PATCH_CANDIDATES:
            if name not in schema or name not in (inv.params or {}):
                continue
            if idx != round_n:
                idx += 1
                continue
            ps = schema[name]
            cur = inv.params[name]
            try:
                if ps.get("type") == "int":
                    new_val = max(int(ps.get("min", 1)), int(cur) // 2)
                else:
                    new_val = max(float(ps.get("min", 1e-6)), float(cur) / 2.0)
            except (TypeError, ValueError):
                return None, "patch value not numeric"
            if new_val == cur:
                return None, "patch would not change param %s" % name
            new_params = dict(inv.params)
            new_params[name] = new_val
            rr = dict(inv.resource_request or {})
            rr["patch_round"] = round_n + 1
            patched = MethodInvocationV1(
                method_id=inv.method_id,
                params=new_params,
                preprocessing=list(inv.preprocessing or []),
                validation=inv.validation,
                hypothesis=inv.hypothesis,
                resource_request=rr,
            )
            return patched, "halved %s %s -> %s" % (name, cur, new_val)
        return None, "no patchable param left"

    def mark_broken(self, method_id: str, reason: str = "") -> None:
        self.registry.set_broken(method_id, reason)


def _contract(profile, manifest) -> Tuple[str, str, str]:
    """Dataset contract: (modality, task_type, metric_name)."""
    modality = ""
    task_type = ""
    metric_name = ""
    if profile is not None:
        modality = str(getattr(profile, "modality", "") or "")
        task_type = str(getattr(profile, "task_type", "") or "")
        metric_name = str(getattr(profile, "metric_name", "") or "")
        if not modality and getattr(profile, "image_width", 0):
            modality = "image"
        if not modality and getattr(profile, "feature_dim", 0) is not None:
            modality = "tabular"
    if manifest is not None:
        if not modality and manifest.get("train_images"):
            modality = "image"
        if not modality and manifest.get("train_csv"):
            modality = "tabular"
        if not task_type:
            task_type = str(manifest.get("task_type") or "")
        if not metric_name:
            metric_name = str(manifest.get("metric_name") or "")
    if modality not in _KNOWN_MODALITIES:
        modality = "unknown"
    return modality, (task_type or "classification").lower(), metric_name
